import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { useState } from "react";
import { Header } from "@/components/Header";
import { Footer } from "@/components/Footer";
import { CartSidebar } from "@/components/CartSidebar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Card } from "@/components/ui/card";
import { useLanguage } from "@/contexts/LanguageContext";
import { useCart } from "@/contexts/CartContext";
import { useToast } from "@/hooks/use-toast";
import { formatPrice } from "@/lib/formatters";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useMutation, useQuery as useAuthQuery } from "@tanstack/react-query";
import type { Product, User, CartItem } from "@shared/schema";
import { ShoppingCart, ArrowLeft, Check } from "lucide-react";
import { Link } from "wouter";
import laptopImage from "@assets/generated_images/gaming_laptop_product_photo.png";
import desktopImage from "@assets/generated_images/desktop_pc_tower_photo.png";
import monitorImage from "@assets/generated_images/gaming_monitor_product_photo.png";
import keyboardImage from "@assets/generated_images/gaming_keyboard_product_photo.png";
import mouseImage from "@assets/generated_images/gaming_mouse_product_photo.png";
import headsetImage from "@assets/generated_images/gaming_headset_product_photo.png";

const imageMap: Record<string, string> = {
  "gaming_laptop_product_photo.png": laptopImage,
  "desktop_pc_tower_photo.png": desktopImage,
  "gaming_monitor_product_photo.png": monitorImage,
  "gaming_keyboard_product_photo.png": keyboardImage,
  "gaming_mouse_product_photo.png": mouseImage,
  "gaming_headset_product_photo.png": headsetImage,
};

interface CartItemWithId extends CartItem {
  id: string;
}

export default function ProductDetail() {
  const [location, setLocation] = useLocation();
  const { language, t } = useLanguage();
  const { cartOpen, setCartOpen } = useCart();
  const { toast } = useToast();
  const [quantity, setQuantity] = useState(1);

  const productId = location.split("/product/")[1];

  const { data: product, isLoading: productLoading } = useQuery<Product>({
    queryKey: [`/api/products/${productId}`],
  });

  const { data: allProducts = [] } = useQuery<Product[]>({
    queryKey: ['/api/products'],
  });

  // Get related products from the same category (excluding current product)
  const relatedProducts = allProducts
    .filter(p => p.category === product?.category && p.id !== product?.id)
    .slice(0, 4);

  const { data: currentUser } = useAuthQuery<User | null>({
    queryKey: ['/api/auth/me'],
  });

  const { data: cartItems = [], isLoading: cartLoading, isError: cartError } = useAuthQuery<CartItemWithId[]>({
    queryKey: ['/api/cart'],
  });

  const updateQuantityMutation = useMutation({
    mutationFn: async ({ id, quantity }: { id: string; quantity: number }) => {
      return await apiRequest('PATCH', `/api/cart/${id}`, { quantity });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/cart'] });
    },
  });

  const removeItemMutation = useMutation({
    mutationFn: async (id: string) => {
      return await apiRequest('DELETE', `/api/cart/${id}`, undefined);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/cart'] });
    },
  });

  const addToCartMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest('POST', '/api/cart', {
        productId,
        quantity,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/cart'] });
      toast({
        title: t('cart.addedToCart'),
        description: `${quantity} ${t('product.addToCart')}`,
      });
      setQuantity(1);
    },
    onError: (error: any) => {
      toast({
        title: t('common.error'),
        description: t('cart.addError'),
        variant: "destructive",
      });
    },
  });

  if (productLoading) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header cartItemsCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)} onCartClick={() => setCartOpen(true)} onSearch={() => {}} />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-muted-foreground">{t('product.loading')}</div>
        </main>
        <Footer />
      </div>
    );
  }

  if (!product) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header cartItemsCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)} onCartClick={() => setCartOpen(true)} onSearch={() => {}} />
        <main className="flex-1 flex items-center justify-center">
          <div className="text-center">
            <p className="text-lg text-muted-foreground mb-4">{t('product.notFound')}</p>
            <Button onClick={() => setLocation("/")}>{t('login.backToHome')}</Button>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  const productName = language === 'ar' ? product.nameAr : product.nameEn;
  const productDescription = language === 'ar' ? product.descriptionAr : product.descriptionEn;

  // Check if image is a URL, uploaded file, or mapped asset
  const getImageSrc = () => {
    if (!product.image) return laptopImage;
    if (product.image.startsWith('/uploads/') || product.image.startsWith('http')) {
      return product.image;
    }
    return imageMap[product.image] || laptopImage;
  };
  const imageSrc = getImageSrc();
  const cartItemsCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  const handleUpdateQuantity = async (id: string, quantity: number) => {
    if (quantity <= 0) {
      handleRemoveItem(id);
      return;
    }
    try {
      await updateQuantityMutation.mutateAsync({ id, quantity });
    } catch {
      toast({
        title: t('common.error'),
        description: t('cart.updateError'),
        variant: "destructive",
      });
    }
  };

  const handleRemoveItem = async (id: string) => {
    try {
      await removeItemMutation.mutateAsync(id);
      toast({
        title: t('cart.removed'),
        description: t('cart.removedDescription'),
      });
    } catch {
      toast({
        title: t('common.error'),
        description: t('cart.removeError'),
        variant: "destructive",
      });
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header cartItemsCount={cartItemsCount} onCartClick={() => setCartOpen(true)} onSearch={() => {}} />

      <CartSidebar
        open={cartOpen}
        onOpenChange={setCartOpen}
        items={cartItems}
        onUpdateQuantity={handleUpdateQuantity}
        onRemoveItem={handleRemoveItem}
        isLoading={cartLoading}
        isError={cartError}
      />

      <main className="flex-1">
        <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-8">
          {/* Back Button */}
          <Button variant="ghost" className="mb-6 gap-2" onClick={() => setLocation("/")} data-testid="button-back">
            <ArrowLeft className="h-4 w-4" />
            {language === 'ar' ? 'العودة للمتجر' : 'Back to Store'}
          </Button>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Product Image */}
            <div data-testid={`product-detail-image-${product.id}`}>
              <Card className="overflow-hidden">
                <div className="aspect-square overflow-hidden bg-muted flex items-center justify-center">
                  <img
                    src={imageSrc}
                    alt={productName}
                    className="w-full h-full object-cover"
                    data-testid={`img-product-detail-${product.id}`}
                  />
                </div>
              </Card>
              {product.badge && (
                <div className="mt-4">
                  <Badge 
                    variant={product.badge.includes('خصم') || product.badge.includes('discount') ? 'destructive' : 'default'}
                    className="text-sm py-1"
                    data-testid={`badge-product-detail-${product.id}`}
                  >
                    {product.badge}
                  </Badge>
                </div>
              )}
            </div>

            {/* Product Details */}
            <div className="space-y-6">
              <div>
                <h1 className="text-3xl md:text-4xl font-bold mb-2" data-testid={`text-product-name-${product.id}`}>
                  {productName}
                </h1>
                <p className="text-lg text-muted-foreground" data-testid={`text-product-description-${product.id}`}>
                  {productDescription}
                </p>
              </div>

              {/* Price Section */}
              <div className="space-y-2">
                <div className="flex items-baseline gap-3">
                  <span className="text-4xl font-bold text-primary" data-testid={`text-price-detail-${product.id}`}>
                    {formatPrice(product.price, language)} {t('common.currency')}
                  </span>
                  {product.oldPrice && (
                    <span className="text-lg text-muted-foreground line-through" data-testid={`text-old-price-detail-${product.id}`}>
                      {formatPrice(product.oldPrice, language)} {t('common.currency')}
                    </span>
                  )}
                </div>
              </div>

              <Separator />

              {/* Stock Status */}
              <div className="flex items-center gap-3">
                {product.inStock ? (
                  <>
                    <Check className="h-5 w-5 text-green-600" />
                    <span className="text-green-600 font-medium" data-testid={`text-in-stock-${product.id}`}>
                      {t('product.inStock')}
                    </span>
                  </>
                ) : (
                  <span className="text-destructive font-medium" data-testid={`text-out-of-stock-${product.id}`}>
                    {t('product.outOfStock')}
                  </span>
                )}
              </div>

              {/* Specifications */}
              {product.specs && product.specs.length > 0 && (
                <>
                  <Separator />
                  <div>
                    <h2 className="text-lg font-bold mb-4" data-testid="text-specifications-title">
                      {t('product.specifications')}
                    </h2>
                    <ul className="space-y-3">
                      {product.specs.map((spec, index) => (
                        <li 
                          key={index} 
                          className="flex items-start gap-3"
                          data-testid={`spec-item-${index}`}
                        >
                          <span className="text-primary mt-1">•</span>
                          <span className="text-sm md:text-base">{spec}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                </>
              )}

              <Separator />

              {/* Add to Cart Section */}
              <div className="space-y-4">
                {product.inStock && (
                  <div className="flex items-center gap-4">
                    <div className="flex items-center border rounded-md">
                      <Button 
                        variant="ghost" 
                        size="sm"
                        onClick={() => setQuantity(Math.max(1, quantity - 1))}
                        data-testid="button-decrease-quantity"
                      >
                        −
                      </Button>
                      <span className="w-12 text-center font-medium" data-testid="text-quantity">
                        {quantity}
                      </span>
                      <Button 
                        variant="ghost" 
                        size="sm"
                        onClick={() => setQuantity(quantity + 1)}
                        data-testid="button-increase-quantity"
                      >
                        +
                      </Button>
                    </div>
                  </div>
                )}

                <Button 
                  className="w-full gap-2 py-6 text-lg"
                  size="lg"
                  disabled={!product.inStock || addToCartMutation.isPending}
                  onClick={() => addToCartMutation.mutate()}
                  data-testid={`button-add-to-cart-detail-${product.id}`}
                >
                  <ShoppingCart className="h-5 w-5" />
                  {addToCartMutation.isPending ? t('product.loading') : t('product.addToCart')}
                </Button>
              </div>
            </div>
          </div>
        </div>

        {/* Related Products Section */}
        {relatedProducts.length > 0 && (
          <section className="mt-12 border-t pt-8">
            <h2 className="text-2xl font-bold mb-6" data-testid="text-related-products-title">
              {language === 'ar' ? 'منتجات ذات صلة' : 'Related Products'}
            </h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {relatedProducts.map((relatedProduct) => {
                const getRelatedImageSrc = () => {
                  if (!relatedProduct.image) return laptopImage;
                  if (relatedProduct.image.startsWith('/uploads/') || relatedProduct.image.startsWith('http')) {
                    return relatedProduct.image;
                  }
                  return imageMap[relatedProduct.image] || laptopImage;
                };
                const relatedProductName = language === 'ar' ? relatedProduct.nameAr : relatedProduct.nameEn;

                return (
                  <Link href={`/product/${relatedProduct.id}`} key={relatedProduct.id}>
                    <Card className="overflow-hidden hover-elevate cursor-pointer" data-testid={`card-related-${relatedProduct.id}`}>
                      <div className="aspect-square overflow-hidden bg-muted">
                        <img
                          src={getRelatedImageSrc()}
                          alt={relatedProductName}
                          className="w-full h-full object-cover"
                          data-testid={`img-related-${relatedProduct.id}`}
                        />
                      </div>
                      <div className="p-3">
                        <h3 className="font-medium text-sm line-clamp-2 mb-2" data-testid={`text-related-name-${relatedProduct.id}`}>
                          {relatedProductName}
                        </h3>
                        <p className="text-primary font-bold" data-testid={`text-related-price-${relatedProduct.id}`}>
                          {formatPrice(relatedProduct.price, language)} {t('common.currency')}
                        </p>
                      </div>
                    </Card>
                  </Link>
                );
              })}
            </div>
          </section>
        )}
      </main>

      <Footer />
    </div>
  );
}

client/src/components/WhatsAppButton.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { useLanguage } from "@/contexts/LanguageContext";
import type { StoreSettings } from "@shared/schema";
import { SiWhatsapp } from "react-icons/si";

export function WhatsAppButton() {
  const { language, t } = useLanguage();

  const { data: settings } = useQuery<StoreSettings>({
    queryKey: ["/api/store-settings"],
  });

  if (!settings?.whatsappNumber) {
    return null;
  }

  const whatsappNumber = settings.whatsappNumber.replace(/\D/g, '');
  const whatsappUrl = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(
    language === 'ar' 
      ? 'السلام عليكم ورحمة الله وبركاته، أود الاستفسار عن...'
      : 'Hi, I would like to inquire about...'
  )}`;

  return (
    <a
      href={whatsappUrl}
      target="_blank"
      rel="noopener noreferrer"
      data-testid="button-whatsapp-chat"
      title={t('footer.whatsapp')}
      className="fixed bottom-6 left-6 z-50 flex items-center justify-center w-14 h-14 bg-[#25D366] hover:bg-[#20BD5C] rounded-full shadow-xl text-white transition-all duration-300 hover:scale-110 animate-pulse hover:animate-none"
      style={{
        boxShadow: '0 4px 20px rgba(37, 211, 102, 0.4)',
      }}
    >
      <SiWhatsapp className="w-7 h-7" />
    </a>
  );
}

client/src/pages/CustomerDashboard.tsx.content:
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Skeleton } from '@/components/ui/skeleton';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { useLanguage } from '@/contexts/LanguageContext';
import { Link } from 'wouter';
import { Header } from '@/components/Header';
import { Footer } from '@/components/Footer';
import { CartSidebar } from '@/components/CartSidebar';
import { useCart } from '@/contexts/CartContext';
import { Package, ShoppingBag, ChevronDown, ChevronUp, MapPin, CreditCard, Calendar, ArrowRight } from 'lucide-react';
import { format } from 'date-fns';
import type { User, CartItem } from '@shared/schema';

interface OrderItem {
  productId: string;
  quantity: number;
  price: string;
  product: {
    nameAr: string;
    nameEn: string;
    image: string;
  };
}

interface Order {
  id: string;
  orderNumber: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  customerAddress: string;
  customerCity: string;
  customerPostal: string;
  paymentMethod: string;
  subtotal: string;
  shipping: string;
  total: string;
  status: string;
  createdAt: string;
  itemsWithProducts: OrderItem[];
}

interface CartItemWithId extends CartItem {
  id: string;
}

export default function CustomerDashboard() {
  const { t, language } = useLanguage();
  const { cartOpen, setCartOpen } = useCart();
  const [expandedOrders, setExpandedOrders] = useState<Set<string>>(new Set());

  const { data: currentUser, isLoading: isAuthLoading, isFetched: isAuthFetched } = useQuery<User | null>({
    queryKey: ['/api/auth/me'],
  });

  const { data: cartItems = [] } = useQuery<CartItemWithId[]>({
    queryKey: ['/api/cart'],
  });

  const isAuthenticated = isAuthFetched && !!currentUser;

  const { data: orders = [], isLoading: isOrdersLoading, isError } = useQuery<Order[]>({
    queryKey: ['/api/orders/my-orders'],
    enabled: isAuthenticated,
  });

  const cartItemsCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  const toggleOrderExpand = (orderId: string) => {
    setExpandedOrders(prev => {
      const newSet = new Set(prev);
      if (newSet.has(orderId)) {
        newSet.delete(orderId);
      } else {
        newSet.add(orderId);
      }
      return newSet;
    });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-yellow-500/10 text-yellow-700 dark:text-yellow-400 border-yellow-500/20';
      case 'confirmed': return 'bg-blue-500/10 text-blue-700 dark:text-blue-400 border-blue-500/20';
      case 'processing': return 'bg-indigo-500/10 text-indigo-700 dark:text-indigo-400 border-indigo-500/20';
      case 'shipped': return 'bg-purple-500/10 text-purple-700 dark:text-purple-400 border-purple-500/20';
      case 'delivered': return 'bg-green-500/10 text-green-700 dark:text-green-400 border-green-500/20';
      case 'cancelled': return 'bg-red-500/10 text-red-700 dark:text-red-400 border-red-500/20';
      default: return 'bg-gray-500/10 text-gray-700 dark:text-gray-400 border-gray-500/20';
    }
  };

  const getPaymentMethodLabel = (method: string) => {
    switch (method) {
      case 'cash_on_delivery': return t('orderConfirmation.cashOnDelivery');
      case 'zain_cash': return t('orderConfirmation.zainCash');
      case 'qicard': return t('orderConfirmation.qiCard');
      default: return method;
    }
  };

  const formatPrice = (price: string | number) => {
    const numPrice = typeof price === 'string' ? parseFloat(price) : price;
    if (language === 'ar') {
      return `${numPrice.toLocaleString('ar-IQ')} د.ع`;
    }
    return `${numPrice.toLocaleString('en-IQ')} IQD`;
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header
          cartItemsCount={cartItemsCount}
          onCartClick={() => setCartOpen(true)}
          onSearch={() => {}}
          onCategorySelect={() => {}}
          searchValue=""
        />
        <main className="flex-1 flex items-center justify-center">
          <div className="space-y-4 text-center">
            <Skeleton className="h-12 w-12 rounded-full mx-auto" />
            <Skeleton className="h-6 w-48 mx-auto" />
          </div>
        </main>
        <Footer />
        <CartSidebar
          open={cartOpen}
          onOpenChange={setCartOpen}
          items={cartItems}
          onUpdateQuantity={() => {}}
          onRemoveItem={() => {}}
          isLoading={false}
          isError={false}
        />
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header
          cartItemsCount={cartItemsCount}
          onCartClick={() => setCartOpen(true)}
          onSearch={() => {}}
          onCategorySelect={() => {}}
          searchValue=""
        />
        <main className="flex-1 flex items-center justify-center">
          <Card className="max-w-md mx-auto">
            <CardHeader className="text-center">
              <Package className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <CardTitle>{t('dashboard.loginRequired')}</CardTitle>
            </CardHeader>
            <CardContent className="text-center">
              <Link href="/login">
                <Button data-testid="button-login-redirect">
                  {t('header.login')}
                  <ArrowRight className="h-4 w-4 ms-2" />
                </Button>
              </Link>
            </CardContent>
          </Card>
        </main>
        <Footer />
        <CartSidebar
          open={cartOpen}
          onOpenChange={setCartOpen}
          items={cartItems}
          onUpdateQuantity={() => {}}
          onRemoveItem={() => {}}
          isLoading={false}
          isError={false}
        />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      <Header
        cartItemsCount={cartItemsCount}
        onCartClick={() => setCartOpen(true)}
        onSearch={() => {}}
        onCategorySelect={() => {}}
        searchValue=""
      />

      <main className="flex-1 py-8">
        <div className="max-w-5xl mx-auto px-4">
          <div className="mb-8">
            <h1 className="text-3xl font-bold mb-2" data-testid="text-dashboard-title">
              {t('dashboard.myOrders')}
            </h1>
            <p className="text-muted-foreground">
              {t('dashboard.orderHistory')}
            </p>
          </div>

          {isOrdersLoading ? (
            <div className="space-y-4">
              {[...Array(3)].map((_, i) => (
                <Card key={i}>
                  <CardHeader>
                    <Skeleton className="h-6 w-32" />
                    <Skeleton className="h-4 w-48" />
                  </CardHeader>
                  <CardContent>
                    <Skeleton className="h-16 w-full" />
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : isError ? (
            <Card>
              <CardContent className="py-12 text-center">
                <p className="text-destructive" data-testid="text-load-error">
                  {t('dashboard.loadError')}
                </p>
              </CardContent>
            </Card>
          ) : orders.length === 0 ? (
            <Card>
              <CardContent className="py-12 text-center">
                <ShoppingBag className="h-16 w-16 mx-auto text-muted-foreground mb-4" />
                <h3 className="text-xl font-semibold mb-2" data-testid="text-no-orders">
                  {t('dashboard.noOrders')}
                </h3>
                <p className="text-muted-foreground mb-6">
                  {t('dashboard.noOrdersDesc')}
                </p>
                <Link href="/">
                  <Button data-testid="button-start-shopping">
                    {t('dashboard.startShopping')}
                    <ArrowRight className="h-4 w-4 ms-2" />
                  </Button>
                </Link>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {orders.map((order) => (
                <Collapsible
                  key={order.id}
                  open={expandedOrders.has(order.id)}
                  onOpenChange={() => toggleOrderExpand(order.id)}
                >
                  <Card data-testid={`order-card-${order.orderNumber}`}>
                    <CollapsibleTrigger asChild>
                      <CardHeader className="cursor-pointer hover-elevate">
                        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                          <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                              <Package className="h-5 w-5 text-primary" />
                            </div>
                            <div>
                              <CardTitle className="text-lg" data-testid={`text-order-number-${order.orderNumber}`}>
                                {order.orderNumber}
                              </CardTitle>
                              <CardDescription className="flex items-center gap-2">
                                <Calendar className="h-3 w-3" />
                                {format(new Date(order.createdAt), 'PPP')}
                              </CardDescription>
                            </div>
                          </div>
                          <div className="flex items-center gap-3">
                            <Badge className={getStatusColor(order.status)} data-testid={`badge-status-${order.orderNumber}`}>
                              {t(`dashboard.status.${order.status}`)}
                            </Badge>
                            <span className="font-bold text-primary" data-testid={`text-total-${order.orderNumber}`}>
                              {formatPrice(order.total)}
                            </span>
                            {expandedOrders.has(order.id) ? (
                              <ChevronUp className="h-5 w-5 text-muted-foreground" />
                            ) : (
                              <ChevronDown className="h-5 w-5 text-muted-foreground" />
                            )}
                          </div>
                        </div>
                      </CardHeader>
                    </CollapsibleTrigger>

                    <CollapsibleContent>
                      <CardContent className="pt-0 space-y-6">
                        <Separator />

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="flex items-start gap-3 p-3 rounded-lg bg-muted/30">
                            <MapPin className="h-5 w-5 text-muted-foreground mt-0.5" />
                            <div>
                              <p className="font-medium text-sm mb-1">{t('dashboard.shippingAddress')}</p>
                              <p className="text-sm text-muted-foreground">{order.customerName}</p>
                              <p className="text-sm text-muted-foreground">{order.customerCity}</p>
                              <p className="text-sm text-muted-foreground">{order.customerAddress}</p>
                            </div>
                          </div>
                          <div className="flex items-start gap-3 p-3 rounded-lg bg-muted/30">
                            <CreditCard className="h-5 w-5 text-muted-foreground mt-0.5" />
                            <div>
                              <p className="font-medium text-sm mb-1">{t('dashboard.paymentMethod')}</p>
                              <p className="text-sm text-muted-foreground">
                                {getPaymentMethodLabel(order.paymentMethod)}
                              </p>
                            </div>
                          </div>
                        </div>

                        <div>
                          <h4 className="font-medium mb-3">{t('dashboard.items')}</h4>
                          <div className="space-y-2">
                            {order.itemsWithProducts.map((item, index) => (
                              <div 
                                key={index} 
                                className="flex items-center gap-3 p-2 rounded-lg bg-muted/20"
                                data-testid={`order-item-${order.orderNumber}-${index}`}
                              >
                                <div className="w-12 h-12 rounded-md bg-background flex items-center justify-center overflow-hidden">
                                  {item.product.image ? (
                                    <img 
                                      src={`/images/${item.product.image}`} 
                                      alt={language === 'ar' ? item.product.nameAr : item.product.nameEn}
                                      className="w-full h-full object-cover"
                                      onError={(e) => {
                                        const target = e.target as HTMLImageElement;
                                        target.style.display = 'none';
                                      }}
                                    />
                                  ) : (
                                    <Package className="h-4 w-4 text-muted-foreground" />
                                  )}
                                </div>
                                <div className="flex-1 min-w-0">
                                  <p className="font-medium text-sm truncate">
                                    {language === 'ar' ? item.product.nameAr : item.product.nameEn}
                                  </p>
                                  <p className="text-xs text-muted-foreground">
                                    {formatPrice(item.price)} × {item.quantity}
                                  </p>
                                </div>
                                <div className="text-end">
                                  <p className="font-medium text-sm">
                                    {formatPrice(parseFloat(item.price) * item.quantity)}
                                  </p>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>

                        <Separator />

                        <div className="space-y-1 text-sm">
                          <div className="flex justify-between">
                            <span className="text-muted-foreground">{t('orderConfirmation.subtotal')}</span>
                            <span>{formatPrice(order.subtotal)}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-muted-foreground">{t('orderConfirmation.shipping')}</span>
                            <span>
                              {parseFloat(order.shipping) === 0 
                                ? t('orderConfirmation.free') 
                                : formatPrice(order.shipping)}
                            </span>
                          </div>
                          <Separator className="my-2" />
                          <div className="flex justify-between font-bold">
                            <span>{t('orderConfirmation.total')}</span>
                            <span className="text-primary">{formatPrice(order.total)}</span>
                          </div>
                        </div>
                      </CardContent>
                    </CollapsibleContent>
                  </Card>
                </Collapsible>
              ))}
            </div>
          )}
        </div>
      </main>

      <Footer />

      <CartSidebar
        open={cartOpen}
        onOpenChange={setCartOpen}
        items={cartItems}
        onUpdateQuantity={() => {}}
        onRemoveItem={() => {}}
        isLoading={false}
        isError={false}
      />
    </div>
  );
}

client/src/pages/TrackOrder.tsx.content:
import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { useLanguage } from '@/contexts/LanguageContext';
import { Link } from 'wouter';
import { apiRequest } from '@/lib/queryClient';
import { Package, Search, MapPin, Phone, Mail, CreditCard, ArrowRight, Home } from 'lucide-react';
import { format } from 'date-fns';

interface OrderItem {
  productId: string;
  quantity: number;
  price: string;
  product: {
    nameAr: string;
    nameEn: string;
    image: string;
  };
}

interface Order {
  id: string;
  orderNumber: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  customerAddress: string;
  customerCity: string;
  customerPostal: string;
  paymentMethod: string;
  subtotal: string;
  shipping: string;
  total: string;
  status: string;
  createdAt: string;
  itemsWithProducts: OrderItem[];
}

export default function TrackOrder() {
  const { t, language } = useLanguage();
  const [orderNumber, setOrderNumber] = useState('');
  const [phone, setPhone] = useState('');
  const [order, setOrder] = useState<Order | null>(null);
  const [formError, setFormError] = useState<string | null>(null);

  const searchMutation = useMutation({
    mutationFn: async (data: { orderNumber: string; phone: string }) => {
      const res = await apiRequest('POST', '/api/orders/lookup', data);
      return res.json();
    },
    onSuccess: (data) => {
      setOrder(data);
      setFormError(null);
    },
    onError: () => {
      setOrder(null);
      setFormError(t('orderTracking.notFoundDesc'));
    },
  });

  const validateForm = (): boolean => {
    const normalizedPhone = phone.replace(/\D/g, '');

    if (!orderNumber || !/^ORD-\d{5}$/.test(orderNumber)) {
      setFormError(t('orderTracking.invalidOrderNumber'));
      return false;
    }

    if (!normalizedPhone || normalizedPhone.length !== 11 || !normalizedPhone.startsWith('07')) {
      setFormError(t('orderTracking.invalidPhone'));
      return false;
    }

    setFormError(null);
    return true;
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (validateForm()) {
      searchMutation.mutate({ 
        orderNumber: orderNumber.trim().toUpperCase(), 
        phone: phone.replace(/\D/g, '') 
      });
    }
  };

  const handleTrackAnother = () => {
    setOrder(null);
    setOrderNumber('');
    setPhone('');
    setFormError(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending': return 'bg-yellow-500/10 text-yellow-700 dark:text-yellow-400 border-yellow-500/20';
      case 'processing': return 'bg-blue-500/10 text-blue-700 dark:text-blue-400 border-blue-500/20';
      case 'shipped': return 'bg-purple-500/10 text-purple-700 dark:text-purple-400 border-purple-500/20';
      case 'delivered': return 'bg-green-500/10 text-green-700 dark:text-green-400 border-green-500/20';
      case 'cancelled': return 'bg-red-500/10 text-red-700 dark:text-red-400 border-red-500/20';
      default: return 'bg-gray-500/10 text-gray-700 dark:text-gray-400 border-gray-500/20';
    }
  };

  const getPaymentMethodLabel = (method: string) => {
    switch (method) {
      case 'cash_on_delivery': return t('orderConfirmation.cashOnDelivery');
      case 'zain_cash': return t('orderConfirmation.zainCash');
      case 'qicard': return t('orderConfirmation.qiCard');
      default: return method;
    }
  };

  const formatPrice = (price: string | number) => {
    const numPrice = typeof price === 'string' ? parseFloat(price) : price;
    if (language === 'ar') {
      return `${numPrice.toLocaleString('ar-IQ')} د.ع`;
    }
    return `${numPrice.toLocaleString('en-IQ')} IQD`;
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-4xl mx-auto px-4 py-8">
        {!order ? (
          <Card>
            <CardHeader>
              <div className="flex items-center gap-2 mb-2">
                <Package className="h-6 w-6 text-primary" />
                <CardTitle data-testid="text-track-order-title">{t('orderTracking.title')}</CardTitle>
              </div>
              <CardDescription>{t('orderTracking.description')}</CardDescription>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSearch} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="orderNumber">{t('orderTracking.orderNumber')}</Label>
                  <Input
                    id="orderNumber"
                    value={orderNumber}
                    onChange={(e) => setOrderNumber(e.target.value.toUpperCase())}
                    placeholder={t('orderTracking.orderNumberPlaceholder')}
                    data-testid="input-order-number"
                    className="font-mono"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="phone">{t('orderTracking.phone')}</Label>
                  <Input
                    id="phone"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    placeholder={t('orderTracking.phonePlaceholder')}
                    data-testid="input-phone"
                  />
                  <p className="text-sm text-muted-foreground">{t('orderTracking.phoneHint')}</p>
                </div>

                {formError && (
                  <div className="text-destructive text-sm" data-testid="text-form-error">
                    {formError}
                  </div>
                )}

                {searchMutation.isError && (
                  <div className="text-destructive text-center py-2" data-testid="text-not-found">
                    {t('orderTracking.notFound')}
                  </div>
                )}

                <div className="flex gap-3 pt-2">
                  <Button 
                    type="submit" 
                    disabled={searchMutation.isPending} 
                    className="flex-1"
                    data-testid="button-track-order"
                  >
                    <Search className="h-4 w-4 me-2" />
                    {searchMutation.isPending ? t('orderTracking.searching') : t('orderTracking.submit')}
                  </Button>
                  <Link href="/">
                    <Button type="button" variant="outline" data-testid="button-back-home">
                      <Home className="h-4 w-4 me-2" />
                      {t('orderTracking.backToHome')}
                    </Button>
                  </Link>
                </div>
              </form>
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <div className="flex justify-between items-start">
                  <div>
                    <CardTitle className="flex items-center gap-2" data-testid="text-order-number-result">
                      <Package className="h-5 w-5 text-primary" />
                      {order.orderNumber}
                    </CardTitle>
                    <CardDescription>
                      {format(new Date(order.createdAt), 'PPP')}
                    </CardDescription>
                  </div>
                  <Badge className={getStatusColor(order.status)} data-testid="badge-order-status">
                    {t(`orderConfirmation.${order.status}`)}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <Card className="bg-muted/50">
                    <CardHeader className="pb-2">
                      <CardTitle className="text-base flex items-center gap-2">
                        <MapPin className="h-4 w-4" />
                        {t('orderConfirmation.shippingInfo')}
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-2 text-sm">
                      <p className="font-medium">{order.customerName}</p>
                      <p className="flex items-center gap-2 text-muted-foreground">
                        <Mail className="h-3 w-3" />
                        {order.customerEmail}
                      </p>
                      <p className="flex items-center gap-2 text-muted-foreground">
                        <Phone className="h-3 w-3" />
                        {order.customerPhone}
                      </p>
                      <Separator className="my-2" />
                      <p>{order.customerCity}</p>
                      <p>{order.customerPostal}</p>
                      <p>{order.customerAddress}</p>
                    </CardContent>
                  </Card>

                  <Card className="bg-muted/50">
                    <CardHeader className="pb-2">
                      <CardTitle className="text-base flex items-center gap-2">
                        <CreditCard className="h-4 w-4" />
                        {t('orderConfirmation.paymentMethod')}
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <p className="font-medium">{getPaymentMethodLabel(order.paymentMethod)}</p>
                    </CardContent>
                  </Card>
                </div>

                <Separator />

                <div>
                  <h3 className="font-semibold mb-4">{t('orderConfirmation.orderItems')}</h3>
                  <div className="space-y-3">
                    {order.itemsWithProducts.map((item, index) => (
                      <div 
                        key={index} 
                        className="flex items-center gap-4 p-3 rounded-lg bg-muted/30"
                        data-testid={`order-item-${index}`}
                      >
                        <div className="w-16 h-16 rounded-md bg-background flex items-center justify-center overflow-hidden">
                          {item.product.image ? (
                            <img 
                              src={`/images/${item.product.image}`} 
                              alt={language === 'ar' ? item.product.nameAr : item.product.nameEn}
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                const target = e.target as HTMLImageElement;
                                target.style.display = 'none';
                              }}
                            />
                          ) : (
                            <Package className="h-6 w-6 text-muted-foreground" />
                          )}
                        </div>
                        <div className="flex-1">
                          <p className="font-medium">
                            {language === 'ar' ? item.product.nameAr : item.product.nameEn}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {t('orderConfirmation.quantity')}: {item.quantity}
                          </p>
                        </div>
                        <div className="text-end">
                          <p className="font-medium">{formatPrice(parseFloat(item.price) * item.quantity)}</p>
                          <p className="text-sm text-muted-foreground">
                            {formatPrice(item.price)} x {item.quantity}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <Separator />

                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-muted-foreground">{t('orderConfirmation.subtotal')}</span>
                    <span>{formatPrice(order.subtotal)}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-muted-foreground">{t('orderConfirmation.shipping')}</span>
                    <span>{parseFloat(order.shipping) === 0 ? t('orderConfirmation.free') : formatPrice(order.shipping)}</span>
                  </div>
                  <Separator />
                  <div className="flex justify-between font-bold text-lg" data-testid="text-order-total">
                    <span>{t('orderConfirmation.total')}</span>
                    <span className="text-primary">{formatPrice(order.total)}</span>
                  </div>
                </div>
              </CardContent>
            </Card>

            <div className="flex gap-3">
              <Button onClick={handleTrackAnother} variant="outline" className="flex-1" data-testid="button-track-another">
                <Search className="h-4 w-4 me-2" />
                {t('orderTracking.trackAnother')}
              </Button>
              <Link href="/">
                <Button className="flex-1" data-testid="button-continue-shopping">
                  {t('orderConfirmation.continueShopping')}
                  <ArrowRight className="h-4 w-4 ms-2" />
                </Button>
              </Link>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

