import { useState } from 'react';
import { useLocation, Link } from 'wouter';
import { useQuery, useMutation } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { Switch } from '@/components/ui/switch';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from '@/components/ui/alert-dialog';
import { useLanguage } from '@/contexts/LanguageContext';
import { useToast } from '@/hooks/use-toast';
import { apiRequest, queryClient } from '@/lib/queryClient';
import { ArrowLeft, ArrowRight, Plus, Pencil, Trash2, Wrench, Shield, User, Users, LogOut } from 'lucide-react';

interface Technician {
  id: string;
  username: string;
  displayName: string;
  isAdmin: number;
  isActive: number;
  permissions: string[];
  createdAt: string;
  updatedAt: string;
}

const AVAILABLE_PERMISSIONS = [
  'view_tickets',
  'update_status',
  'manage_tickets',
  'manage_technicians',
];

export default function TechnicianManagement() {
  const [, navigate] = useLocation();
  const { t, language } = useLanguage();
  const { toast } = useToast();
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [editingTechnician, setEditingTechnician] = useState<Technician | null>(null);
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    displayName: '',
    isAdmin: false,
    permissions: [] as string[],
  });

  const { data: currentTechnician, isLoading: isAuthLoading, error: authError } = useQuery<Technician>({
    queryKey: ['/api/technician/auth/me'],
    retry: false,
  });

  const { data: technicians, isLoading: isTechniciansLoading } = useQuery<Technician[]>({
    queryKey: ['/api/admin/technicians'],
    enabled: !!currentTechnician && currentTechnician.isAdmin === 1,
  });

  const createMutation = useMutation({
    mutationFn: async (data: any) => {
      await apiRequest('POST', '/api/admin/technicians', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/technicians'] });
      toast({
        title: t('technician.management.created'),
      });
      setIsAddDialogOpen(false);
      resetForm();
    },
    onError: (error: any) => {
      toast({
        title: t('common.error'),
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: any }) => {
      await apiRequest('PATCH', `/api/admin/technicians/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/technicians'] });
      toast({
        title: t('technician.management.updated'),
      });
      setEditingTechnician(null);
      resetForm();
    },
    onError: (error: any) => {
      toast({
        title: t('common.error'),
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      await apiRequest('DELETE', `/api/admin/technicians/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/technicians'] });
      toast({
        title: t('technician.management.deleted'),
      });
    },
    onError: (error: any) => {
      toast({
        title: t('common.error'),
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  const logoutMutation = useMutation({
    mutationFn: async () => {
      await apiRequest('POST', '/api/technician/auth/logout');
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/technician/auth/me'] });
      navigate('/technician/login');
    },
    onError: () => {
      toast({
        title: t('common.error'),
        description: t('common.errorOccurred'),
        variant: 'destructive',
      });
    },
  });

  const handleLogout = () => {
    logoutMutation.mutate();
  };

  const resetForm = () => {
    setFormData({
      username: '',
      password: '',
      displayName: '',
      isAdmin: false,
      permissions: [],
    });
  };

  const handleAdd = () => {
    resetForm();
    setIsAddDialogOpen(true);
  };

  const handleEdit = (technician: Technician) => {
    setEditingTechnician(technician);
    setFormData({
      username: technician.username,
      password: '',
      displayName: technician.displayName,
      isAdmin: technician.isAdmin === 1,
      permissions: technician.permissions || [],
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingTechnician) {
      const updateData: any = {
        username: formData.username,
        displayName: formData.displayName,
        isAdmin: formData.isAdmin,
        permissions: formData.permissions,
      };
      if (formData.password) {
        updateData.password = formData.password;
      }
      updateMutation.mutate({ id: editingTechnician.id, data: updateData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const togglePermission = (permission: string) => {
    setFormData(prev => ({
      ...prev,
      permissions: prev.permissions.includes(permission)
        ? prev.permissions.filter(p => p !== permission)
        : [...prev.permissions, permission],
    }));
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <Wrench className="h-8 w-8 animate-spin mx-auto mb-4 text-primary" />
          <p>{t('common.loading')}</p>
        </div>
      </div>
    );
  }

  if (authError || !currentTechnician) {
    navigate('/technician/login');
    return null;
  }

  if (currentTechnician.isAdmin !== 1) {
    navigate('/technician/dashboard');
    return null;
  }

  const isRTL = language === 'ar';
  const BackIcon = isRTL ? ArrowRight : ArrowLeft;

  const TechnicianForm = () => (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="space-y-2">
        <Label htmlFor="username">{t('technician.management.username')}</Label>
        <Input
          id="username"
          value={formData.username}
          onChange={(e) => setFormData({ ...formData, username: e.target.value })}
          required
          minLength={3}
          data-testid="input-technician-form-username"
        />
      </div>

      <div className="space-y-2">
        <Label htmlFor="displayName">{t('technician.management.displayName')}</Label>
        <Input
          id="displayName"
          value={formData.displayName}
          onChange={(e) => setFormData({ ...formData, displayName: e.target.value })}
          required
          minLength={2}
          data-testid="input-technician-form-displayname"
        />
      </div>

      <div className="space-y-2">
        <Label htmlFor="password">
          {editingTechnician ? t('technician.management.newPassword') : t('technician.management.password')}
        </Label>
        <Input
          id="password"
          type="password"
          value={formData.password}
          onChange={(e) => setFormData({ ...formData, password: e.target.value })}
          required={!editingTechnician}
          minLength={6}
          placeholder={editingTechnician ? t('technician.management.leaveBlankPassword') : ''}
          data-testid="input-technician-form-password"
        />
      </div>

      <div className="flex items-center justify-between">
        <Label htmlFor="isAdmin">{t('technician.management.isAdmin')}</Label>
        <Switch
          id="isAdmin"
          checked={formData.isAdmin}
          onCheckedChange={(checked) => setFormData({ ...formData, isAdmin: checked })}
          data-testid="switch-technician-form-admin"
        />
      </div>

      <div className="space-y-3">
        <Label>{t('technician.management.permissions')}</Label>
        <div className="space-y-2">
          {AVAILABLE_PERMISSIONS.map((permission) => (
            <div key={permission} className="flex items-center gap-2">
              <Checkbox
                id={permission}
                checked={formData.permissions.includes(permission)}
                onCheckedChange={() => togglePermission(permission)}
                data-testid={`checkbox-permission-${permission}`}
              />
              <Label htmlFor={permission} className="font-normal cursor-pointer">
                {t(`technician.management.permission.${permission}`)}
              </Label>
            </div>
          ))}
        </div>
      </div>

      <DialogFooter>
        <Button type="submit" disabled={createMutation.isPending || updateMutation.isPending} data-testid="button-technician-form-submit">
          {editingTechnician ? t('common.save') : t('technician.management.addNew')}
        </Button>
      </DialogFooter>
    </form>
  );

  return (
    <div className="min-h-screen bg-background">
      <div className="border-b bg-card">
        <div className="max-w-7xl mx-auto px-4 py-4 flex flex-wrap justify-between items-center gap-4">
          <div className="flex items-center gap-3">
            <Link href="/technician/dashboard">
              <Button variant="ghost" size="icon" data-testid="button-back-to-dashboard">
                <BackIcon className="h-5 w-5" />
              </Button>
            </Link>
            <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center">
              <Users className="h-5 w-5 text-primary" />
            </div>
            <div>
              <h1 className="text-xl font-bold" data-testid="text-technician-management-title">
                {t('technician.management.title')}
              </h1>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
              <DialogTrigger asChild>
                <Button onClick={handleAdd} data-testid="button-add-technician">
                  <Plus className="h-4 w-4 me-2" />
                  {t('technician.management.addNew')}
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>{t('technician.management.addNew')}</DialogTitle>
                </DialogHeader>
                <TechnicianForm />
              </DialogContent>
            </Dialog>
            <Button variant="outline" onClick={handleLogout} disabled={logoutMutation.isPending} data-testid="button-technician-logout">
              <LogOut className="h-4 w-4 me-2" />
              {t('technician.dashboard.logout')}
            </Button>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {isTechniciansLoading ? (
          <div className="text-center py-12">
            {t('common.loading')}
          </div>
        ) : technicians && technicians.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {technicians.map((technician) => (
              <Card key={technician.id} data-testid={`card-technician-${technician.id}`}>
                <CardHeader>
                  <div className="flex justify-between items-start">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-muted rounded-full flex items-center justify-center">
                        {technician.isAdmin === 1 ? (
                          <Shield className="h-5 w-5 text-primary" />
                        ) : (
                          <User className="h-5 w-5 text-muted-foreground" />
                        )}
                      </div>
                      <div>
                        <CardTitle className="text-lg">{technician.displayName}</CardTitle>
                        <CardDescription>@{technician.username}</CardDescription>
                      </div>
                    </div>
                    <Badge className={technician.isActive === 1 ? 'bg-green-500/10 text-green-700' : 'bg-red-500/10 text-red-700'}>
                      {technician.isActive === 1 ? t('technician.management.active') : t('technician.management.inactive')}
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex flex-wrap gap-1">
                    {technician.isAdmin === 1 && (
                      <Badge variant="secondary" className="text-xs">
                        <Shield className="h-3 w-3 me-1" />
                        {t('technician.management.isAdmin')}
                      </Badge>
                    )}
                    {technician.permissions?.map((perm) => (
                      <Badge key={perm} variant="outline" className="text-xs">
                        {t(`technician.management.permission.${perm}`)}
                      </Badge>
                    ))}
                  </div>

                  <div className="flex gap-2">
                    <Dialog open={editingTechnician?.id === technician.id} onOpenChange={(open) => !open && setEditingTechnician(null)}>
                      <DialogTrigger asChild>
                        <Button variant="outline" size="sm" onClick={() => handleEdit(technician)} data-testid={`button-edit-technician-${technician.id}`}>
                          <Pencil className="h-4 w-4 me-1" />
                          {t('technician.management.edit')}
                        </Button>
                      </DialogTrigger>
                      <DialogContent>
                        <DialogHeader>
                          <DialogTitle>{t('technician.management.edit')}</DialogTitle>
                        </DialogHeader>
                        <TechnicianForm />
                      </DialogContent>
                    </Dialog>

                    {technician.id !== currentTechnician?.id && (
                      <AlertDialog>
                        <AlertDialogTrigger asChild>
                          <Button variant="destructive" size="sm" data-testid={`button-delete-technician-${technician.id}`}>
                            <Trash2 className="h-4 w-4 me-1" />
                            {t('technician.management.delete')}
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>{t('technician.management.confirmDelete')}</AlertDialogTitle>
                            <AlertDialogDescription>
                              {technician.displayName} (@{technician.username})
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>{t('common.cancel')}</AlertDialogCancel>
                            <AlertDialogAction
                              onClick={() => deleteMutation.mutate(technician.id)}
                              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                            >
                              {t('technician.management.delete')}
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    )}
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        ) : (
          <Card>
            <CardContent className="py-12 text-center">
              <p className="text-muted-foreground">
                {t('technician.management.noTechnicians')}
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

client/src/pages/AdminCustomers.tsx.content:
import { useState, useEffect } from "react";
import { useLocation, Link } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useLanguage } from "@/contexts/LanguageContext";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Pencil, Trash2, Users, Loader2 } from "lucide-react";
import { AdminNav } from "@/components/AdminNav";

interface AdminUser {
  id: string;
  username: string;
  name: string;
  role: string;
}

interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  createdAt: string;
}

export default function AdminCustomers() {
  const [, setLocation] = useLocation();
  const { t, language } = useLanguage();
  const { toast } = useToast();
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deleteCustomerId, setDeleteCustomerId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    password: "",
  });

  const { data: currentAdmin, isLoading: authLoading, isError: authError } = useQuery<AdminUser>({
    queryKey: ['/api/admin/auth/me'],
    retry: false,
  });

  useEffect(() => {
    if (!authLoading && (authError || !currentAdmin)) {
      localStorage.removeItem("adminAuth");
      setLocation("/admin/login");
    }
  }, [authLoading, authError, currentAdmin, setLocation]);

  const { data: customers = [], isLoading } = useQuery<Customer[]>({
    queryKey: ["/api/admin/customers"],
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: any }) => {
      return apiRequest("PATCH", `/api/admin/customers/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/customers"] });
      setEditingCustomer(null);
      resetForm();
      toast({
        title: t('admin.customers.updateSuccess'),
      });
    },
    onError: () => {
      toast({
        title: t('admin.customers.updateError'),
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/admin/customers/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/customers"] });
      setDeleteCustomerId(null);
      toast({
        title: t('admin.customers.deleteSuccess'),
      });
    },
    onError: () => {
      toast({
        title: t('admin.customers.deleteError'),
        variant: "destructive",
      });
    },
  });

  const resetForm = () => {
    setFormData({
      name: "",
      email: "",
      phone: "",
      password: "",
    });
  };

  const handleEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      name: customer.name,
      email: customer.email,
      phone: customer.phone,
      password: "",
    });
  };

  const handleSubmit = () => {
    if (!editingCustomer) return;

    const updateData: any = {
      name: formData.name,
      email: formData.email,
      phone: formData.phone,
    };

    if (formData.password.trim()) {
      updateData.password = formData.password;
    }

    updateMutation.mutate({
      id: editingCustomer.id,
      data: updateData,
    });
  };

  const handleDelete = (id: string) => {
    setDeleteCustomerId(id);
  };

  const confirmDelete = () => {
    if (deleteCustomerId) {
      deleteMutation.mutate(deleteCustomerId);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString(
      language === 'ar' ? 'ar-IQ' : 'en-US',
      { year: 'numeric', month: 'short', day: 'numeric' }
    );
  };

  if (authLoading || isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin" />
      </div>
    );
  }

  if (!currentAdmin) {
    return null;
  }

  return (
    <div className="min-h-screen bg-background" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <AdminNav currentAdmin={currentAdmin} />

      <main className="max-w-7xl mx-auto px-4 py-8">
        {customers.length === 0 ? (
          <Card>
            <CardContent className="py-16 text-center">
              <Users className="mx-auto h-12 w-12 text-muted-foreground mb-4" />
              <h3 className="text-lg font-semibold mb-2">{t('admin.customers.noCustomers')}</h3>
              <p className="text-muted-foreground">{t('admin.customers.noCustomersDesc')}</p>
            </CardContent>
          </Card>
        ) : (
          <Card>
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t('admin.customers.name')}</TableHead>
                    <TableHead>{t('admin.customers.email')}</TableHead>
                    <TableHead>{t('admin.customers.phone')}</TableHead>
                    <TableHead>{t('admin.customers.registeredAt')}</TableHead>
                    <TableHead className="text-end">{t('admin.customers.actions')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {customers.map((customer) => (
                    <TableRow key={customer.id} data-testid={`row-customer-${customer.id}`}>
                      <TableCell className="font-medium" data-testid={`text-customer-name-${customer.id}`}>
                        {customer.name}
                      </TableCell>
                      <TableCell data-testid={`text-customer-email-${customer.id}`}>
                        {customer.email}
                      </TableCell>
                      <TableCell data-testid={`text-customer-phone-${customer.id}`}>
                        {customer.phone}
                      </TableCell>
                      <TableCell>
                        {formatDate(customer.createdAt)}
                      </TableCell>
                      <TableCell className="text-end">
                        <div className="flex gap-2 justify-end">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleEdit(customer)}
                            data-testid={`button-edit-customer-${customer.id}`}
                          >
                            <Pencil className="h-4 w-4 me-1" />
                            {t('admin.customers.edit')}
                          </Button>
                          <Button
                            variant="destructive"
                            size="sm"
                            onClick={() => handleDelete(customer.id)}
                            data-testid={`button-delete-customer-${customer.id}`}
                          >
                            <Trash2 className="h-4 w-4 me-1" />
                            {t('admin.customers.delete')}
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        )}
      </main>

      <Dialog open={!!editingCustomer} onOpenChange={(open) => !open && setEditingCustomer(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t('admin.customers.editCustomer')}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">{t('admin.customers.name')}</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                data-testid="input-customer-name"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="email">{t('admin.customers.email')}</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                data-testid="input-customer-email"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="phone">{t('admin.customers.phone')}</Label>
              <Input
                id="phone"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                data-testid="input-customer-phone"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">{t('admin.customers.password')}</Label>
              <Input
                id="password"
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                placeholder={t('admin.customers.passwordHint')}
                data-testid="input-customer-password"
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setEditingCustomer(null)}
              data-testid="button-cancel-edit"
            >
              {t('admin.customers.cancel')}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={updateMutation.isPending}
              data-testid="button-save-customer"
            >
              {updateMutation.isPending ? t('admin.customers.updating') : t('admin.customers.save')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteCustomerId} onOpenChange={(open) => !open && setDeleteCustomerId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('admin.customers.deleteTitle')}</AlertDialogTitle>
            <AlertDialogDescription>
              {t('admin.customers.confirmDelete')}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel data-testid="button-cancel-delete">
              {t('admin.customers.cancel')}
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              disabled={deleteMutation.isPending}
              data-testid="button-confirm-delete"
            >
              {deleteMutation.isPending ? t('admin.customers.deleting') : t('admin.customers.delete')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

server/admin-notifications.ts.content:
import { WebSocketServer, WebSocket } from 'ws';
import { Server, IncomingMessage } from 'http';
import { neon } from '@neondatabase/serverless';

interface AdminNotification {
  type: 'new_order' | 'order_update';
  data: {
    orderId: string;
    orderNumber: string;
    customerName: string;
    total: string;
    createdAt: string;
  };
  timestamp: string;
}

function parseCookies(cookieHeader: string | undefined): Record<string, string> {
  const cookies: Record<string, string> = {};
  if (!cookieHeader) return cookies;

  cookieHeader.split(';').forEach(cookie => {
    const [name, ...rest] = cookie.split('=');
    const value = rest.join('=');
    if (name && value) {
      cookies[name.trim()] = decodeURIComponent(value.trim());
    }
  });

  return cookies;
}

function parseSessionId(signedCookie: string, secret: string): string | null {
  if (!signedCookie.startsWith('s:')) {
    return null;
  }

  const value = signedCookie.slice(2);
  const dotIndex = value.lastIndexOf('.');
  if (dotIndex === -1) {
    return null;
  }

  return value.slice(0, dotIndex);
}

class AdminNotificationService {
  private wss: WebSocketServer | null = null;
  private clients: Set<WebSocket> = new Set();
  private sessionSecret: string = process.env.SESSION_SECRET || 'default-secret-please-change-in-production';
  private sql: ReturnType<typeof neon> | null = null;

  initialize(server: Server) {
    // Initialize neon HTTP client for session verification
    if (process.env.DATABASE_URL) {
      this.sql = neon(process.env.DATABASE_URL);
    }

    this.wss = new WebSocketServer({ 
      server, 
      path: '/ws/admin',
      verifyClient: async (info, callback) => {
        try {
          const cookies = parseCookies(info.req.headers.cookie);
          const sessionCookie = cookies['connect.sid'];

          if (!sessionCookie) {
            console.log('WebSocket connection rejected: No session cookie');
            callback(false, 401, 'Unauthorized');
            return;
          }

          const sessionId = parseSessionId(sessionCookie, this.sessionSecret);
          if (!sessionId) {
            console.log('WebSocket connection rejected: Invalid session cookie');
            callback(false, 401, 'Unauthorized');
            return;
          }

          // Check if admin session exists in database
          const isAdmin = await this.verifyAdminSession(sessionId);
          if (!isAdmin) {
            console.log('WebSocket connection rejected: Not an admin session');
            callback(false, 403, 'Forbidden');
            return;
          }

          console.log('WebSocket connection authorized for admin');
          callback(true);
        } catch (error) {
          console.error('WebSocket auth error:', error);
          callback(false, 500, 'Internal Server Error');
        }
      }
    });

    this.wss.on('connection', (ws: WebSocket, req: IncomingMessage) => {
      console.log('Admin WebSocket client connected (authenticated)');
      this.clients.add(ws);

      ws.on('close', () => {
        console.log('Admin WebSocket client disconnected');
        this.clients.delete(ws);
      });

      ws.on('error', (error) => {
        console.error('WebSocket error:', error);
        this.clients.delete(ws);
      });

      ws.send(JSON.stringify({ type: 'connected', message: 'Connected to admin notifications' }));
    });

    console.log('Admin WebSocket server initialized on /ws/admin (with authentication)');
  }

  private async verifyAdminSession(sessionId: string): Promise<boolean> {
    try {
      if (!this.sql) {
        console.error('Database not initialized for session verification');
        return false;
      }

      // Use neon HTTP client for session verification
      const result = await this.sql`SELECT sess FROM "session" WHERE sid = ${sessionId}`;

      if (result.length === 0) {
        return false;
      }

      const session = result[0].sess as any;
      // Check if session has adminId (set during admin login)
      return session && typeof session.adminId === 'string' && session.adminId.length > 0;
    } catch (error) {
      console.error('Error verifying admin session:', error);
      return false;
    }
  }

  broadcastNewOrder(order: {
    id: string;
    orderNumber: string;
    customerName: string;
    total: string;
    createdAt: string | Date;
  }) {
    const notification: AdminNotification = {
      type: 'new_order',
      data: {
        orderId: order.id,
        orderNumber: order.orderNumber,
        customerName: order.customerName,
        total: order.total,
        createdAt: typeof order.createdAt === 'string' ? order.createdAt : order.createdAt.toISOString(),
      },
      timestamp: new Date().toISOString(),
    };

    const message = JSON.stringify(notification);

    this.clients.forEach((client) => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    });

    console.log(`Broadcasted new order notification: ${order.orderNumber} to ${this.clients.size} clients`);
  }

  getConnectedClientsCount(): number {
    return this.clients.size;
  }
}

export const adminNotifications = new AdminNotificationService();

