const CACHE_VERSION = 'v1';
const STATIC_CACHE = `alain-static-${CACHE_VERSION}`;
const DYNAMIC_CACHE = `alain-dynamic-${CACHE_VERSION}`;

const STATIC_ASSETS = [
  '/',
  '/manifest.json',
  '/favicon.png',
  '/icons/icon-72x72.png',
  '/icons/icon-96x96.png',
  '/icons/icon-192x192.png',
  '/icons/icon-512x512.png'
];

const OFFLINE_PAGE = '/';

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC_CACHE);
      await cache.addAll(STATIC_ASSETS);

      try {
        const response = await fetch('/');
        if (response.ok) {
          const text = await response.text();
          const scriptMatches = text.match(/src="(\/assets\/[^"]+\.js)"/g) || [];
          const cssMatches = text.match(/href="(\/assets\/[^"]+\.css)"/g) || [];

          const assetUrls = [
            ...scriptMatches.map(m => m.match(/src="([^"]+)"/)?.[1]).filter(Boolean),
            ...cssMatches.map(m => m.match(/href="([^"]+)"/)?.[1]).filter(Boolean)
          ];

          for (const url of assetUrls) {
            try {
              await cache.add(url);
            } catch (e) {
              console.log('Failed to cache:', url);
            }
          }
        }
      } catch (e) {
        console.log('Could not fetch app shell assets');
      }
    })()
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames
          .filter((name) => name !== STATIC_CACHE && name !== DYNAMIC_CACHE)
          .map((name) => caches.delete(name))
      );
    })
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (request.method !== 'GET') {
    return;
  }

  if (url.pathname.startsWith('/api/')) {
    event.respondWith(networkFirst(request));
    return;
  }

  if (request.destination === 'image') {
    event.respondWith(cacheFirst(request));
    return;
  }

  if (url.origin === location.origin) {
    event.respondWith(staleWhileRevalidate(request));
    return;
  }

  event.respondWith(networkFirst(request));
});

async function cacheFirst(request) {
  const cachedResponse = await caches.match(request);
  if (cachedResponse) {
    return cachedResponse;
  }

  try {
    const networkResponse = await fetch(request);
    if (networkResponse.ok) {
      const cache = await caches.open(DYNAMIC_CACHE);
      cache.put(request, networkResponse.clone());
    }
    return networkResponse;
  } catch (error) {
    return new Response('Offline', { status: 503 });
  }
}

async function networkFirst(request) {
  try {
    const networkResponse = await fetch(request);
    if (networkResponse.ok) {
      const cache = await caches.open(DYNAMIC_CACHE);
      cache.put(request, networkResponse.clone());
    }
    return networkResponse;
  } catch (error) {
    const cachedResponse = await caches.match(request);
    if (cachedResponse) {
      return cachedResponse;
    }
    return new Response(JSON.stringify({ error: 'Offline' }), {
      status: 503,
      headers: { 'Content-Type': 'application/json' }
    });
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(DYNAMIC_CACHE);
  const cachedResponse = await cache.match(request);

  const fetchPromise = fetch(request).then((networkResponse) => {
    if (networkResponse.ok) {
      cache.put(request, networkResponse.clone());
    }
    return networkResponse;
  }).catch(() => cachedResponse);

  return cachedResponse || fetchPromise;
}

self.addEventListener('push', (event) => {
  const data = event.data?.json() || {};
  const title = data.title || 'العين لتجارة الحاسبات';
  const options = {
    body: data.body || 'لديك إشعار جديد',
    icon: '/icons/icon-192x192.png',
    badge: '/icons/icon-72x72.png',
    dir: 'rtl',
    lang: 'ar',
    vibrate: [100, 50, 100],
    data: data.url || '/',
    actions: [
      { action: 'open', title: 'فتح' },
      { action: 'close', title: 'إغلاق' }
    ]
  };

  event.waitUntil(
    self.registration.showNotification(title, options)
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  if (event.action === 'close') {
    return;
  }

  event.waitUntil(
    clients.openWindow(event.notification.data || '/')
  );
});

server/qicard.ts.content:
interface QiCardConfig {
  merchantId: string;
  apiKey: string;
  secretKey: string;
  isTest: boolean;
}

interface PaymentInitData {
  amount: number;
  orderId: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  description: string;
  redirectUrl: string;
  callbackUrl: string;
}

interface PaymentInitResponse {
  success: boolean;
  transactionId?: string;
  paymentUrl?: string;
  error?: string;
}

interface PaymentStatusResponse {
  success: boolean;
  status?: string;
  transactionId?: string;
  orderId?: string;
  amount?: number;
  error?: string;
}

interface CallbackData {
  transactionId: string;
  orderId: string;
  status: string;
  amount: number;
  message?: string;
}

class QiCardService {
  private config: QiCardConfig;
  private baseUrl: string;

  constructor() {
    this.config = {
      merchantId: process.env.QICARD_MERCHANT_ID || '',
      apiKey: process.env.QICARD_API_KEY || '',
      secretKey: process.env.QICARD_SECRET_KEY || '',
      isTest: process.env.QICARD_TEST_MODE !== 'false',
    };

    this.baseUrl = this.config.isTest 
      ? 'https://api-test.qi.iq/v1' 
      : 'https://api.qi.iq/v1';
  }

  isConfigured(): boolean {
    return !!(this.config.merchantId && this.config.apiKey && this.config.secretKey);
  }

  getConfig(): { isTest: boolean; isConfigured: boolean } {
    return {
      isTest: this.config.isTest,
      isConfigured: this.isConfigured(),
    };
  }

  private async getAuthToken(): Promise<string | null> {
    try {
      const response = await fetch(`${this.baseUrl}/auth/token`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          merchantId: this.config.merchantId,
          apiKey: this.config.apiKey,
          secretKey: this.config.secretKey,
        }),
      });

      if (!response.ok) {
        console.error('QiCard auth error:', await response.text());
        return null;
      }

      const result = await response.json();
      return result.token || result.access_token;
    } catch (error) {
      console.error('QiCard auth error:', error);
      return null;
    }
  }

  async initPayment(data: PaymentInitData): Promise<PaymentInitResponse> {
    if (!this.isConfigured()) {
      return {
        success: false,
        error: 'QiCard is not configured. Please set QICARD_MERCHANT_ID, QICARD_API_KEY, and QICARD_SECRET_KEY.',
      };
    }

    try {
      const token = await this.getAuthToken();
      if (!token) {
        return {
          success: false,
          error: 'Failed to authenticate with QiCard',
        };
      }

      const response = await fetch(`${this.baseUrl}/payment/init`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({
          merchantId: this.config.merchantId,
          amount: data.amount,
          currency: 'IQD',
          orderId: data.orderId,
          description: data.description,
          customer: {
            name: data.customerName,
            email: data.customerEmail,
            phone: data.customerPhone,
          },
          redirectUrl: data.redirectUrl,
          callbackUrl: data.callbackUrl,
          language: 'ar',
        }),
      });

      const result = await response.json();

      if (!response.ok) {
        console.error('QiCard init error:', result);
        return {
          success: false,
          error: result.message || result.error || 'Failed to initialize payment',
        };
      }

      if (result.transactionId && result.paymentUrl) {
        return {
          success: true,
          transactionId: result.transactionId,
          paymentUrl: result.paymentUrl,
        };
      }

      return {
        success: false,
        error: result.message || 'Unknown error initializing payment',
      };
    } catch (error) {
      console.error('QiCard init error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to initialize payment',
      };
    }
  }

  async verifyPayment(transactionId: string): Promise<PaymentStatusResponse> {
    if (!this.isConfigured()) {
      return {
        success: false,
        error: 'QiCard is not configured',
      };
    }

    try {
      const token = await this.getAuthToken();
      if (!token) {
        return {
          success: false,
          error: 'Failed to authenticate with QiCard',
        };
      }

      const response = await fetch(`${this.baseUrl}/payment/status/${transactionId}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });

      const result = await response.json();

      if (!response.ok) {
        console.error('QiCard verify error:', result);
        return {
          success: false,
          error: result.message || 'Failed to verify payment',
        };
      }

      return {
        success: true,
        status: result.status,
        transactionId: result.transactionId,
        orderId: result.orderId,
        amount: result.amount,
      };
    } catch (error) {
      console.error('QiCard verify error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to verify payment',
      };
    }
  }

  parseCallback(body: any): CallbackData | null {
    try {
      if (!body.transactionId || !body.orderId || !body.status) {
        console.error('Invalid QiCard callback data:', body);
        return null;
      }

      return {
        transactionId: body.transactionId,
        orderId: body.orderId,
        status: body.status,
        amount: body.amount || 0,
        message: body.message,
      };
    } catch (error) {
      console.error('QiCard callback parse error:', error);
      return null;
    }
  }

  mapStatusToPaymentStatus(qiCardStatus: string): 'success' | 'failed' | 'pending' {
    const statusMap: Record<string, 'success' | 'failed' | 'pending'> = {
      'completed': 'success',
      'success': 'success',
      'paid': 'success',
      'approved': 'success',
      'failed': 'failed',
      'declined': 'failed',
      'cancelled': 'failed',
      'expired': 'failed',
      'pending': 'pending',
      'processing': 'pending',
    };

    return statusMap[qiCardStatus.toLowerCase()] || 'pending';
  }
}

export const qicard = new QiCardService();

