import { useEffect, useState } from "react";
import { useLocation, Link } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { TrendingUp, TrendingDown, Minus, Plus, Edit, Trash2, MemoryStick, HardDrive, CircuitBoard, Loader2, Globe } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { AdminNav } from "@/components/AdminNav";
import { Badge } from "@/components/ui/badge";
import type { MarketPrice } from "@shared/schema";

interface AdminUser {
  id: string;
  username: string;
  name: string;
  role: string;
}

const componentTypes = [
  { value: "ram", labelAr: "ذاكرة عشوائية (RAM)", labelEn: "RAM Memory", icon: MemoryStick },
  { value: "ssd", labelAr: "أقراص SSD", labelEn: "SSD Drives", icon: HardDrive },
  { value: "m2", labelAr: "أقراص M.2 NVMe", labelEn: "M.2 NVMe Drives", icon: CircuitBoard },
];

const popularBrands = {
  ram: ["Kingston", "Corsair", "G.Skill", "Crucial", "TeamGroup", "ADATA"],
  ssd: ["Samsung", "Western Digital", "Crucial", "Kingston", "SanDisk", "Seagate"],
  m2: ["Samsung", "Western Digital", "Crucial", "Kingston", "Sabrent", "Seagate"],
};

const commonCapacities = {
  ram: ["4GB", "8GB", "16GB", "32GB", "64GB"],
  ssd: ["128GB", "256GB", "512GB", "1TB", "2TB", "4TB"],
  m2: ["256GB", "512GB", "1TB", "2TB", "4TB"],
};

export default function AdminMarketPrices() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const { t, language } = useLanguage();
  const [activeTab, setActiveTab] = useState("ram");
  const [showAddPrice, setShowAddPrice] = useState(false);
  const [showEditPrice, setShowEditPrice] = useState<MarketPrice | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    componentType: "ram",
    nameAr: "",
    nameEn: "",
    brand: "",
    capacity: "",
    specs: "",
    currentPrice: "",
  });

  const { data: currentAdmin, isLoading: authLoading, isError: authError } = useQuery<AdminUser>({
    queryKey: ['/api/admin/auth/me'],
    retry: false,
  });

  useEffect(() => {
    if (!authLoading && (authError || !currentAdmin)) {
      localStorage.removeItem("adminAuth");
      setLocation("/admin/login");
    }
  }, [authLoading, authError, currentAdmin, setLocation]);

  const { data: marketPrices = [], isLoading } = useQuery<MarketPrice[]>({
    queryKey: ['/api/admin/market-prices'],
    enabled: !!currentAdmin,
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const response = await apiRequest('POST', '/api/admin/market-prices', data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/market-prices'] });
      setShowAddPrice(false);
      resetForm();
      toast({
        title: language === 'ar' ? "تم إضافة السعر" : "Price Added",
        description: language === 'ar' ? "تم إضافة سعر المكون بنجاح" : "Component price added successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في إضافة السعر" : "Failed to add price",
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof formData> }) => {
      const response = await apiRequest('PUT', `/api/admin/market-prices/${id}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/market-prices'] });
      setShowEditPrice(null);
      resetForm();
      toast({
        title: language === 'ar' ? "تم تحديث السعر" : "Price Updated",
        description: language === 'ar' ? "تم تحديث سعر المكون بنجاح" : "Component price updated successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في تحديث السعر" : "Failed to update price",
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return await apiRequest('DELETE', `/api/admin/market-prices/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/market-prices'] });
      setDeleteId(null);
      toast({
        title: language === 'ar' ? "تم الحذف" : "Deleted",
        description: language === 'ar' ? "تم حذف السعر بنجاح" : "Price deleted successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في حذف السعر" : "Failed to delete price",
        variant: "destructive",
      });
    },
  });

  const resetForm = () => {
    setFormData({
      componentType: activeTab,
      nameAr: "",
      nameEn: "",
      brand: "",
      capacity: "",
      specs: "",
      currentPrice: "",
    });
  };

  const handleAddClick = () => {
    setFormData(prev => ({ ...prev, componentType: activeTab }));
    setShowAddPrice(true);
  };

  const handleEditClick = (price: MarketPrice) => {
    setFormData({
      componentType: price.componentType,
      nameAr: price.nameAr,
      nameEn: price.nameEn,
      brand: price.brand,
      capacity: price.capacity,
      specs: price.specs || "",
      currentPrice: price.currentPrice,
    });
    setShowEditPrice(price);
  };

  const handleSubmit = () => {
    if (showEditPrice) {
      updateMutation.mutate({ id: showEditPrice.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const getPriceChange = (current: string, previous: string | null) => {
    if (!previous) return { change: 0, percentage: 0 };
    const currentNum = parseFloat(current);
    const previousNum = parseFloat(previous);
    const change = currentNum - previousNum;
    const percentage = ((change / previousNum) * 100);
    return { change, percentage };
  };

  const filterByType = (type: string) => {
    return marketPrices.filter(p => p.componentType === type);
  };

  const formatPrice = (price: string) => {
    return new Intl.NumberFormat('ar-IQ').format(parseFloat(price));
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin" />
      </div>
    );
  }

  if (!currentAdmin) {
    return null;
  }

  return (
    <div className="min-h-screen bg-background" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <AdminNav currentAdmin={currentAdmin} />

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-2xl font-bold">
              {language === 'ar' ? 'أسعار المكونات اليومية' : 'Daily Component Prices'}
            </h2>
            <p className="text-muted-foreground">
              {language === 'ar' ? 'تحديث يومي لأسعار الذاكرة والتخزين في السوق العراقي' : 'Daily price updates for memory and storage in the Iraqi market'}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <Link href="/admin/external-prices">
              <Button variant="outline" data-testid="link-external-prices">
                <Globe className="w-4 h-4 me-2" />
                {language === 'ar' ? 'الأسعار العالمية' : 'International Prices'}
              </Button>
            </Link>
            <Button onClick={handleAddClick} data-testid="button-add-price">
              <Plus className="w-4 h-4 me-2" />
              {language === 'ar' ? 'إضافة سعر' : 'Add Price'}
            </Button>
          </div>
        </div>

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="mb-6">
            {componentTypes.map(type => (
              <TabsTrigger key={type.value} value={type.value} data-testid={`tab-${type.value}`}>
                <type.icon className="w-4 h-4 me-2" />
                {language === 'ar' ? type.labelAr : type.labelEn}
              </TabsTrigger>
            ))}
          </TabsList>

          {componentTypes.map(type => (
            <TabsContent key={type.value} value={type.value}>
              {isLoading ? (
                <div className="flex items-center justify-center py-12">
                  <Loader2 className="w-8 h-8 animate-spin" />
                </div>
              ) : filterByType(type.value).length === 0 ? (
                <Card>
                  <CardContent className="py-12 text-center">
                    <type.icon className="w-12 h-12 mx-auto mb-4 text-muted-foreground opacity-50" />
                    <p className="text-muted-foreground">
                      {language === 'ar' ? 'لا توجد أسعار مسجلة بعد' : 'No prices recorded yet'}
                    </p>
                    <Button variant="outline" className="mt-4" onClick={handleAddClick}>
                      <Plus className="w-4 h-4 me-2" />
                      {language === 'ar' ? 'إضافة أول سعر' : 'Add First Price'}
                    </Button>
                  </CardContent>
                </Card>
              ) : (
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                  {filterByType(type.value).map(price => {
                    const { change, percentage } = getPriceChange(price.currentPrice, price.previousPrice);
                    const isUp = change > 0;
                    const isDown = change < 0;

                    return (
                      <Card key={price.id} data-testid={`price-card-${price.id}`}>
                        <CardHeader className="pb-2">
                          <div className="flex items-start justify-between gap-2">
                            <div>
                              <CardTitle className="text-base">
                                {language === 'ar' ? price.nameAr : price.nameEn}
                              </CardTitle>
                              <CardDescription>
                                {price.brand} - {price.capacity}
                              </CardDescription>
                            </div>
                            <div className="flex gap-1">
                              <Button 
                                variant="ghost" 
                                size="icon" 
                                className="h-8 w-8"
                                onClick={() => handleEditClick(price)}
                                data-testid={`button-edit-${price.id}`}
                              >
                                <Edit className="w-4 h-4" />
                              </Button>
                              <Button 
                                variant="ghost" 
                                size="icon" 
                                className="h-8 w-8 text-destructive"
                                onClick={() => setDeleteId(price.id)}
                                data-testid={`button-delete-${price.id}`}
                              >
                                <Trash2 className="w-4 h-4" />
                              </Button>
                            </div>
                          </div>
                        </CardHeader>
                        <CardContent>
                          {price.specs && (
                            <p className="text-sm text-muted-foreground mb-2">{price.specs}</p>
                          )}
                          <div className="flex items-end justify-between">
                            <div>
                              <p className="text-2xl font-bold">
                                {formatPrice(price.currentPrice)}
                                <span className="text-sm font-normal text-muted-foreground ms-1">
                                  {language === 'ar' ? 'د.ع' : 'IQD'}
                                </span>
                              </p>
                              {price.previousPrice && (
                                <p className="text-sm text-muted-foreground line-through">
                                  {formatPrice(price.previousPrice)} {language === 'ar' ? 'د.ع' : 'IQD'}
                                </p>
                              )}
                            </div>
                            {price.previousPrice && (
                              <Badge 
                                variant={isDown ? "default" : isUp ? "destructive" : "secondary"}
                                className={`flex items-center gap-1 ${isDown ? 'bg-green-500 hover:bg-green-600' : ''}`}
                              >
                                {isUp ? (
                                  <TrendingUp className="w-3 h-3" />
                                ) : isDown ? (
                                  <TrendingDown className="w-3 h-3" />
                                ) : (
                                  <Minus className="w-3 h-3" />
                                )}
                                {percentage.toFixed(1)}%
                              </Badge>
                            )}
                          </div>
                          <p className="text-xs text-muted-foreground mt-2">
                            {language === 'ar' ? 'آخر تحديث:' : 'Last update:'}{' '}
                            {new Date(price.priceDate).toLocaleDateString(language === 'ar' ? 'ar-IQ' : 'en-US')}
                          </p>
                        </CardContent>
                      </Card>
                    );
                  })}
                </div>
              )}
            </TabsContent>
          ))}
        </Tabs>
      </main>

      <Dialog open={showAddPrice || !!showEditPrice} onOpenChange={(open) => {
        if (!open) {
          setShowAddPrice(false);
          setShowEditPrice(null);
          resetForm();
        }
      }}>
        <DialogContent className="max-w-md" dir={language === 'ar' ? 'rtl' : 'ltr'}>
          <DialogHeader>
            <DialogTitle>
              {showEditPrice 
                ? (language === 'ar' ? 'تعديل السعر' : 'Edit Price')
                : (language === 'ar' ? 'إضافة سعر جديد' : 'Add New Price')
              }
            </DialogTitle>
            <DialogDescription>
              {language === 'ar' 
                ? 'أدخل تفاصيل المكون والسعر الحالي'
                : 'Enter component details and current price'
              }
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>{language === 'ar' ? 'نوع المكون' : 'Component Type'}</Label>
              <Select
                value={formData.componentType}
                onValueChange={(value) => setFormData(prev => ({ ...prev, componentType: value }))}
              >
                <SelectTrigger data-testid="select-component-type">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {componentTypes.map(type => (
                    <SelectItem key={type.value} value={type.value}>
                      {language === 'ar' ? type.labelAr : type.labelEn}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>{language === 'ar' ? 'الاسم بالعربية' : 'Arabic Name'}</Label>
                <Input
                  value={formData.nameAr}
                  onChange={(e) => setFormData(prev => ({ ...prev, nameAr: e.target.value }))}
                  placeholder={language === 'ar' ? 'مثال: رام كورسير' : 'e.g., رام كورسير'}
                  data-testid="input-name-ar"
                />
              </div>
              <div className="space-y-2">
                <Label>{language === 'ar' ? 'الاسم بالإنجليزية' : 'English Name'}</Label>
                <Input
                  value={formData.nameEn}
                  onChange={(e) => setFormData(prev => ({ ...prev, nameEn: e.target.value }))}
                  placeholder="e.g., Corsair RAM"
                  data-testid="input-name-en"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>{language === 'ar' ? 'العلامة التجارية' : 'Brand'}</Label>
                <Select
                  value={formData.brand}
                  onValueChange={(value) => setFormData(prev => ({ ...prev, brand: value }))}
                >
                  <SelectTrigger data-testid="select-brand">
                    <SelectValue placeholder={language === 'ar' ? 'اختر العلامة' : 'Select brand'} />
                  </SelectTrigger>
                  <SelectContent>
                    {popularBrands[formData.componentType as keyof typeof popularBrands]?.map(brand => (
                      <SelectItem key={brand} value={brand}>{brand}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>{language === 'ar' ? 'السعة' : 'Capacity'}</Label>
                <Select
                  value={formData.capacity}
                  onValueChange={(value) => setFormData(prev => ({ ...prev, capacity: value }))}
                >
                  <SelectTrigger data-testid="select-capacity">
                    <SelectValue placeholder={language === 'ar' ? 'اختر السعة' : 'Select capacity'} />
                  </SelectTrigger>
                  <SelectContent>
                    {commonCapacities[formData.componentType as keyof typeof commonCapacities]?.map(cap => (
                      <SelectItem key={cap} value={cap}>{cap}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'المواصفات (اختياري)' : 'Specs (Optional)'}</Label>
              <Input
                value={formData.specs}
                onChange={(e) => setFormData(prev => ({ ...prev, specs: e.target.value }))}
                placeholder={language === 'ar' ? 'مثال: DDR4 3200MHz' : 'e.g., DDR4 3200MHz'}
                data-testid="input-specs"
              />
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'السعر الحالي (د.ع)' : 'Current Price (IQD)'}</Label>
              <Input
                type="number"
                value={formData.currentPrice}
                onChange={(e) => setFormData(prev => ({ ...prev, currentPrice: e.target.value }))}
                placeholder="0"
                data-testid="input-current-price"
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowAddPrice(false);
                setShowEditPrice(null);
                resetForm();
              }}
            >
              {language === 'ar' ? 'إلغاء' : 'Cancel'}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={createMutation.isPending || updateMutation.isPending || !formData.nameAr || !formData.nameEn || !formData.brand || !formData.capacity || !formData.currentPrice}
              data-testid="button-submit-price"
            >
              {(createMutation.isPending || updateMutation.isPending) && (
                <Loader2 className="w-4 h-4 animate-spin me-2" />
              )}
              {showEditPrice 
                ? (language === 'ar' ? 'تحديث' : 'Update')
                : (language === 'ar' ? 'إضافة' : 'Add')
              }
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent dir={language === 'ar' ? 'rtl' : 'ltr'}>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {language === 'ar' ? 'تأكيد الحذف' : 'Confirm Delete'}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {language === 'ar' 
                ? 'هل أنت متأكد من حذف هذا السعر؟ لا يمكن التراجع عن هذا الإجراء.'
                : 'Are you sure you want to delete this price? This action cannot be undone.'
              }
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{language === 'ar' ? 'إلغاء' : 'Cancel'}</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deleteId && deleteMutation.mutate(deleteId)}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleteMutation.isPending && <Loader2 className="w-4 h-4 animate-spin me-2" />}
              {language === 'ar' ? 'حذف' : 'Delete'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

client/src/components/AdminNav.tsx.content:
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { 
  LayoutDashboard, 
  Package, 
  Users, 
  Settings, 
  TrendingUp, 
  Warehouse,
  GraduationCap,
  LogOut,
  Loader2,
  ShoppingCart,
  BarChart3,
  Clock
} from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";

interface AdminNavProps {
  currentAdmin: { id: string; username: string; name: string; role: string } | null;
}

export function AdminNav({ currentAdmin }: AdminNavProps) {
  const [location, setLocation] = useLocation();
  const { language } = useLanguage();

  const logoutMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest('POST', '/api/admin/auth/logout');
    },
    onSuccess: () => {
      localStorage.removeItem("adminAuth");
      queryClient.clear();
      setLocation("/admin/login");
    },
  });

  const navItems = [
    { href: "/admin/dashboard", icon: LayoutDashboard, labelAr: "لوحة التحكم", labelEn: "Dashboard" },
    { href: "/admin/pos", icon: ShoppingCart, labelAr: "نقطة البيع", labelEn: "POS" },
    { href: "/admin/sales", icon: BarChart3, labelAr: "المبيعات", labelEn: "Sales" },
    { href: "/admin/products", icon: Package, labelAr: "المنتجات", labelEn: "Products" },
    { href: "/admin/inventory", icon: Warehouse, labelAr: "المخزون", labelEn: "Inventory" },
    { href: "/admin/customers", icon: Users, labelAr: "العملاء", labelEn: "Customers" },
    { href: "/admin/attendance", icon: Clock, labelAr: "الحضور", labelEn: "Attendance" },
    { href: "/admin/market-prices", icon: TrendingUp, labelAr: "أسعار السوق", labelEn: "Market Prices" },
    { href: "/admin/programs", icon: GraduationCap, labelAr: "البرامج", labelEn: "Programs" },
    { href: "/admin/settings", icon: Settings, labelAr: "الإعدادات", labelEn: "Settings" },
  ];

  return (
    <header className="border-b bg-card" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <div className="max-w-7xl mx-auto px-4 py-3">
        <div className="flex items-center justify-between gap-4">
          <nav className="flex items-center gap-1 flex-wrap">
            {navItems.map((item) => {
              const isActive = location === item.href;
              const Icon = item.icon;
              return (
                <Link key={item.href} href={item.href}>
                  <Button 
                    variant={isActive ? "secondary" : "ghost"} 
                    size="sm"
                    className="gap-1"
                    data-testid={`nav-${item.href.split('/').pop()}`}
                  >
                    <Icon className="w-4 h-4" />
                    <span className="hidden md:inline">
                      {language === 'ar' ? item.labelAr : item.labelEn}
                    </span>
                  </Button>
                </Link>
              );
            })}
          </nav>

          <div className="flex items-center gap-2">
            {currentAdmin && (
              <span className="text-sm text-muted-foreground hidden sm:inline">
                {currentAdmin.name}
              </span>
            )}
            <Button
              variant="ghost"
              size="sm"
              onClick={() => logoutMutation.mutate()}
              disabled={logoutMutation.isPending}
              data-testid="button-logout"
            >
              {logoutMutation.isPending ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <LogOut className="w-4 h-4" />
              )}
              <span className="hidden sm:inline ms-1">
                {language === 'ar' ? 'خروج' : 'Logout'}
              </span>
            </Button>
          </div>
        </div>
      </div>
    </header>
  );
}

client/src/pages/AdminInventory.tsx.content:
import { useEffect, useState } from "react";
import { useLocation, Link } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { 
  Loader2, 
  Package, 
  AlertTriangle, 
  Plus, 
  Minus, 
  History,
  Search,
  Edit,
  Save,
  X,
  Upload,
  Download,
  FileSpreadsheet,
  CheckCircle2,
  XCircle
} from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { AdminNav } from "@/components/AdminNav";
import type { Product, InventoryMovement } from "@shared/schema";

interface AdminUser {
  id: string;
  username: string;
  name: string;
  role: string;
}

interface ProductWithInventory extends Product {
  stockQuantity: number;
  lowStockThreshold: number;
  sku: string | null;
}

export default function AdminInventory() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const { language } = useLanguage();
  const [activeTab, setActiveTab] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [showAdjustDialog, setShowAdjustDialog] = useState<ProductWithInventory | null>(null);
  const [showHistoryDialog, setShowHistoryDialog] = useState<ProductWithInventory | null>(null);
  const [editingProduct, setEditingProduct] = useState<string | null>(null);
  const [editValues, setEditValues] = useState({ stockQuantity: "", lowStockThreshold: "", sku: "" });

  const [adjustmentData, setAdjustmentData] = useState({
    type: "adjustment" as "adjustment" | "purchase" | "return",
    quantity: "",
    reason: "",
  });

  const [showImportDialog, setShowImportDialog] = useState(false);
  const [csvFile, setCsvFile] = useState<File | null>(null);
  const [importResults, setImportResults] = useState<{
    totalRows: number;
    results: {
      success: number;
      failed: number;
      created: number;
      updated: number;
      errors: Array<{ row: number; error: string }>;
    };
  } | null>(null);

  const { data: currentAdmin, isLoading: authLoading, isError: authError } = useQuery<AdminUser>({
    queryKey: ['/api/admin/auth/me'],
    retry: false,
  });

  useEffect(() => {
    if (!authLoading && (authError || !currentAdmin)) {
      localStorage.removeItem("adminAuth");
      setLocation("/admin/login");
    }
  }, [authLoading, authError, currentAdmin, setLocation]);

  const { data: products = [], isLoading } = useQuery<ProductWithInventory[]>({
    queryKey: ['/api/admin/inventory'],
    enabled: !!currentAdmin,
  });

  const { data: lowStockProducts = [] } = useQuery<ProductWithInventory[]>({
    queryKey: ['/api/admin/inventory/low-stock'],
    enabled: !!currentAdmin,
  });

  const { data: movements = [] } = useQuery<InventoryMovement[]>({
    queryKey: ['/api/admin/inventory/movements', showHistoryDialog?.id],
    queryFn: async () => {
      if (!showHistoryDialog?.id) return [];
      const response = await fetch(`/api/admin/inventory/movements?productId=${showHistoryDialog.id}`);
      if (!response.ok) throw new Error('Failed to fetch movements');
      return response.json();
    },
    enabled: !!showHistoryDialog,
  });

  const updateStockMutation = useMutation({
    mutationFn: async ({ productId, data }: { productId: string; data: { stockQuantity?: number; lowStockThreshold?: number; sku?: string } }) => {
      const response = await apiRequest('PUT', `/api/admin/inventory/${productId}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/inventory'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/inventory/low-stock'] });
      setEditingProduct(null);
      toast({
        title: language === 'ar' ? "تم التحديث" : "Updated",
        description: language === 'ar' ? "تم تحديث المخزون بنجاح" : "Inventory updated successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في تحديث المخزون" : "Failed to update inventory",
        variant: "destructive",
      });
    },
  });

  const adjustStockMutation = useMutation({
    mutationFn: async ({ productId, data }: { productId: string; data: { movementType: string; quantityChange: number; reason?: string } }) => {
      const response = await apiRequest('POST', `/api/admin/inventory/${productId}/adjust`, data);
      return response.json();
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/inventory'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/inventory/low-stock'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/inventory/movements', variables.productId] });
      setShowAdjustDialog(null);
      setAdjustmentData({ type: "adjustment", quantity: "", reason: "" });
      toast({
        title: language === 'ar' ? "تم التعديل" : "Adjusted",
        description: language === 'ar' ? "تم تعديل المخزون بنجاح" : "Stock adjusted successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في تعديل المخزون" : "Failed to adjust stock",
        variant: "destructive",
      });
    },
  });

  const importMutation = useMutation({
    mutationFn: async (csvData: string) => {
      const response = await apiRequest('POST', '/api/admin/inventory/import', { csvData });
      return response.json();
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/inventory'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/inventory/low-stock'] });
      setImportResults(data);
      setCsvFile(null);
      toast({
        title: language === 'ar' ? "تم الاستيراد" : "Import Complete",
        description: language === 'ar' 
          ? `تم استيراد ${data.results.success} منتج بنجاح`
          : `Successfully imported ${data.results.success} products`,
      });
    },
    onError: (error: any) => {
      toast({
        title: language === 'ar' ? "خطأ في الاستيراد" : "Import Error",
        description: error.message || (language === 'ar' ? "فشل استيراد البيانات" : "Failed to import data"),
        variant: "destructive",
      });
    },
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setCsvFile(file);
      setImportResults(null);
    }
  };

  const handleImportSubmit = async () => {
    if (!csvFile) return;

    const text = await csvFile.text();
    importMutation.mutate(text);
  };

  const handleDownloadTemplate = () => {
    window.open('/api/admin/inventory/import/template', '_blank');
  };

  const handleStartEdit = (product: ProductWithInventory) => {
    setEditingProduct(product.id);
    setEditValues({
      stockQuantity: String(product.stockQuantity),
      lowStockThreshold: String(product.lowStockThreshold),
      sku: product.sku || "",
    });
  };

  const handleSaveEdit = (productId: string) => {
    updateStockMutation.mutate({
      productId,
      data: {
        stockQuantity: parseInt(editValues.stockQuantity) || 0,
        lowStockThreshold: parseInt(editValues.lowStockThreshold) || 5,
        sku: editValues.sku || undefined,
      },
    });
  };

  const handleCancelEdit = () => {
    setEditingProduct(null);
    setEditValues({ stockQuantity: "", lowStockThreshold: "", sku: "" });
  };

  const handleAdjustSubmit = () => {
    if (!showAdjustDialog || !adjustmentData.quantity) return;

    const quantity = parseInt(adjustmentData.quantity);
    if (isNaN(quantity) || quantity === 0) return;

    adjustStockMutation.mutate({
      productId: showAdjustDialog.id,
      data: {
        movementType: adjustmentData.type,
        quantityChange: quantity,
        reason: adjustmentData.reason || undefined,
      },
    });
  };

  const filteredProducts = products.filter(product => {
    const matchesSearch = searchQuery === "" || 
      (language === 'ar' ? product.nameAr : product.nameEn).toLowerCase().includes(searchQuery.toLowerCase()) ||
      (product.sku || "").toLowerCase().includes(searchQuery.toLowerCase());

    if (activeTab === "low-stock") {
      return matchesSearch && product.stockQuantity <= product.lowStockThreshold;
    }
    if (activeTab === "out-of-stock") {
      return matchesSearch && product.stockQuantity === 0;
    }
    return matchesSearch;
  });

  const formatPrice = (price: string | number) => {
    return new Intl.NumberFormat('ar-IQ').format(typeof price === 'string' ? parseFloat(price) : price);
  };

  const getMovementTypeLabel = (type: string) => {
    const types: Record<string, { ar: string; en: string }> = {
      adjustment: { ar: "تعديل", en: "Adjustment" },
      sale: { ar: "بيع", en: "Sale" },
      purchase: { ar: "شراء", en: "Purchase" },
      return: { ar: "إرجاع", en: "Return" },
      import: { ar: "استيراد", en: "Import" },
    };
    return types[type]?.[language === 'ar' ? 'ar' : 'en'] || type;
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin" />
      </div>
    );
  }

  if (!currentAdmin) {
    return null;
  }

  return (
    <div className="min-h-screen bg-background" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <AdminNav currentAdmin={currentAdmin} />

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="grid gap-4 md:grid-cols-3 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                {language === 'ar' ? 'إجمالي المنتجات' : 'Total Products'}
              </CardTitle>
              <Package className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{products.length}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                {language === 'ar' ? 'مخزون منخفض' : 'Low Stock'}
              </CardTitle>
              <AlertTriangle className="h-4 w-4 text-yellow-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-yellow-600">{lowStockProducts.length}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                {language === 'ar' ? 'نفد من المخزون' : 'Out of Stock'}
              </CardTitle>
              <AlertTriangle className="h-4 w-4 text-red-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-red-600">
                {products.filter(p => p.stockQuantity === 0).length}
              </div>
            </CardContent>
          </Card>
        </div>

        <Card>
          <CardHeader>
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <CardTitle>{language === 'ar' ? 'قائمة المخزون' : 'Inventory List'}</CardTitle>
                <CardDescription>
                  {language === 'ar' ? 'إدارة مستويات المخزون للمنتجات' : 'Manage product stock levels'}
                </CardDescription>
              </div>
              <div className="flex items-center gap-2">
                <div className="relative">
                  <Search className="absolute start-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder={language === 'ar' ? 'بحث...' : 'Search...'}
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="ps-9 w-64"
                    data-testid="input-search"
                  />
                </div>
                <Button
                  variant="outline"
                  onClick={() => {
                    setShowImportDialog(true);
                    setImportResults(null);
                    setCsvFile(null);
                  }}
                  data-testid="button-import"
                >
                  <Upload className="w-4 h-4 me-2" />
                  {language === 'ar' ? 'استيراد CSV' : 'Import CSV'}
                </Button>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <TabsList className="mb-4">
                <TabsTrigger value="all" data-testid="tab-all">
                  <Package className="w-4 h-4 me-2" />
                  {language === 'ar' ? 'الكل' : 'All'}
                </TabsTrigger>
                <TabsTrigger value="low-stock" data-testid="tab-low-stock">
                  <AlertTriangle className="w-4 h-4 me-2" />
                  {language === 'ar' ? 'مخزون منخفض' : 'Low Stock'}
                  {lowStockProducts.length > 0 && (
                    <Badge variant="destructive" className="ms-2">{lowStockProducts.length}</Badge>
                  )}
                </TabsTrigger>
                <TabsTrigger value="out-of-stock" data-testid="tab-out-of-stock">
                  <AlertTriangle className="w-4 h-4 me-2" />
                  {language === 'ar' ? 'نفد' : 'Out'}
                </TabsTrigger>
              </TabsList>

              <TabsContent value={activeTab}>
                {isLoading ? (
                  <div className="flex items-center justify-center py-12">
                    <Loader2 className="w-8 h-8 animate-spin" />
                  </div>
                ) : filteredProducts.length === 0 ? (
                  <div className="text-center py-12 text-muted-foreground">
                    <Package className="w-12 h-12 mx-auto mb-4 opacity-50" />
                    <p>{language === 'ar' ? 'لا توجد منتجات' : 'No products found'}</p>
                  </div>
                ) : (
                  <div className="rounded-md border overflow-x-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>{language === 'ar' ? 'المنتج' : 'Product'}</TableHead>
                          <TableHead>{language === 'ar' ? 'SKU' : 'SKU'}</TableHead>
                          <TableHead>{language === 'ar' ? 'السعر' : 'Price'}</TableHead>
                          <TableHead>{language === 'ar' ? 'الكمية' : 'Quantity'}</TableHead>
                          <TableHead>{language === 'ar' ? 'حد التنبيه' : 'Alert Threshold'}</TableHead>
                          <TableHead>{language === 'ar' ? 'الحالة' : 'Status'}</TableHead>
                          <TableHead>{language === 'ar' ? 'الإجراءات' : 'Actions'}</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {filteredProducts.map((product) => {
                          const isEditing = editingProduct === product.id;
                          const isLowStock = product.stockQuantity <= product.lowStockThreshold && product.stockQuantity > 0;
                          const isOutOfStock = product.stockQuantity === 0;

                          return (
                            <TableRow key={product.id} data-testid={`row-product-${product.id}`}>
                              <TableCell>
                                <div className="flex items-center gap-3">
                                  {product.image && (
                                    <img 
                                      src={product.image} 
                                      alt={language === 'ar' ? product.nameAr : product.nameEn}
                                      className="w-10 h-10 rounded object-cover"
                                    />
                                  )}
                                  <div>
                                    <p className="font-medium">
                                      {language === 'ar' ? product.nameAr : product.nameEn}
                                    </p>
                                    <p className="text-sm text-muted-foreground">{product.category}</p>
                                  </div>
                                </div>
                              </TableCell>
                              <TableCell>
                                {isEditing ? (
                                  <Input
                                    value={editValues.sku}
                                    onChange={(e) => setEditValues(prev => ({ ...prev, sku: e.target.value }))}
                                    className="w-24"
                                    placeholder="SKU"
                                    data-testid={`input-sku-${product.id}`}
                                  />
                                ) : (
                                  <span className="text-muted-foreground">{product.sku || "-"}</span>
                                )}
                              </TableCell>
                              <TableCell>
                                {formatPrice(product.price)} {language === 'ar' ? 'د.ع' : 'IQD'}
                              </TableCell>
                              <TableCell>
                                {isEditing ? (
                                  <Input
                                    type="number"
                                    value={editValues.stockQuantity}
                                    onChange={(e) => setEditValues(prev => ({ ...prev, stockQuantity: e.target.value }))}
                                    className="w-20"
                                    min="0"
                                    data-testid={`input-quantity-${product.id}`}
                                  />
                                ) : (
                                  <span className={isOutOfStock ? "text-red-600 font-bold" : isLowStock ? "text-yellow-600 font-bold" : ""}>
                                    {product.stockQuantity}
                                  </span>
                                )}
                              </TableCell>
                              <TableCell>
                                {isEditing ? (
                                  <Input
                                    type="number"
                                    value={editValues.lowStockThreshold}
                                    onChange={(e) => setEditValues(prev => ({ ...prev, lowStockThreshold: e.target.value }))}
                                    className="w-20"
                                    min="0"
                                    data-testid={`input-threshold-${product.id}`}
                                  />
                                ) : (
                                  product.lowStockThreshold
                                )}
                              </TableCell>
                              <TableCell>
                                {isOutOfStock ? (
                                  <Badge variant="destructive">{language === 'ar' ? 'نفد' : 'Out of Stock'}</Badge>
                                ) : isLowStock ? (
                                  <Badge variant="secondary" className="bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200">
                                    {language === 'ar' ? 'منخفض' : 'Low Stock'}
                                  </Badge>
                                ) : (
                                  <Badge variant="secondary" className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">
                                    {language === 'ar' ? 'متوفر' : 'In Stock'}
                                  </Badge>
                                )}
                              </TableCell>
                              <TableCell>
                                <div className="flex items-center gap-1">
                                  {isEditing ? (
                                    <>
                                      <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => handleSaveEdit(product.id)}
                                        disabled={updateStockMutation.isPending}
                                        data-testid={`button-save-${product.id}`}
                                      >
                                        {updateStockMutation.isPending ? (
                                          <Loader2 className="h-4 w-4 animate-spin" />
                                        ) : (
                                          <Save className="h-4 w-4 text-green-600" />
                                        )}
                                      </Button>
                                      <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={handleCancelEdit}
                                        data-testid={`button-cancel-${product.id}`}
                                      >
                                        <X className="h-4 w-4 text-red-600" />
                                      </Button>
                                    </>
                                  ) : (
                                    <>
                                      <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => handleStartEdit(product)}
                                        data-testid={`button-edit-${product.id}`}
                                      >
                                        <Edit className="h-4 w-4" />
                                      </Button>
                                      <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => setShowAdjustDialog(product)}
                                        data-testid={`button-adjust-${product.id}`}
                                      >
                                        <Plus className="h-4 w-4" />
                                      </Button>
                                      <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => setShowHistoryDialog(product)}
                                        data-testid={`button-history-${product.id}`}
                                      >
                                        <History className="h-4 w-4" />
                                      </Button>
                                    </>
                                  )}
                                </div>
                              </TableCell>
                            </TableRow>
                          );
                        })}
                      </TableBody>
                    </Table>
                  </div>
                )}
              </TabsContent>
            </Tabs>
          </CardContent>
        </Card>
      </main>

      <Dialog open={!!showAdjustDialog} onOpenChange={(open) => {
        if (!open) {
          setShowAdjustDialog(null);
          setAdjustmentData({ type: "adjustment", quantity: "", reason: "" });
        }
      }}>
        <DialogContent className="max-w-md" dir={language === 'ar' ? 'rtl' : 'ltr'}>
          <DialogHeader>
            <DialogTitle>
              {language === 'ar' ? 'تعديل المخزون' : 'Adjust Stock'}
            </DialogTitle>
            <DialogDescription>
              {showAdjustDialog && (language === 'ar' ? showAdjustDialog.nameAr : showAdjustDialog.nameEn)}
              <br />
              {language === 'ar' ? 'الكمية الحالية:' : 'Current quantity:'} {showAdjustDialog?.stockQuantity}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>{language === 'ar' ? 'نوع الحركة' : 'Movement Type'}</Label>
              <Select
                value={adjustmentData.type}
                onValueChange={(value: "adjustment" | "purchase" | "return") => setAdjustmentData(prev => ({ ...prev, type: value }))}
              >
                <SelectTrigger data-testid="select-movement-type">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="adjustment">{language === 'ar' ? 'تعديل' : 'Adjustment'}</SelectItem>
                  <SelectItem value="purchase">{language === 'ar' ? 'شراء / إضافة' : 'Purchase / Add'}</SelectItem>
                  <SelectItem value="return">{language === 'ar' ? 'إرجاع' : 'Return'}</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'الكمية (موجب للإضافة، سالب للخصم)' : 'Quantity (positive to add, negative to subtract)'}</Label>
              <Input
                type="number"
                value={adjustmentData.quantity}
                onChange={(e) => setAdjustmentData(prev => ({ ...prev, quantity: e.target.value }))}
                placeholder="e.g., 10 or -5"
                data-testid="input-adjust-quantity"
              />
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'السبب (اختياري)' : 'Reason (optional)'}</Label>
              <Textarea
                value={adjustmentData.reason}
                onChange={(e) => setAdjustmentData(prev => ({ ...prev, reason: e.target.value }))}
                placeholder={language === 'ar' ? 'سبب التعديل...' : 'Reason for adjustment...'}
                data-testid="input-adjust-reason"
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowAdjustDialog(null);
                setAdjustmentData({ type: "adjustment", quantity: "", reason: "" });
              }}
            >
              {language === 'ar' ? 'إلغاء' : 'Cancel'}
            </Button>
            <Button
              onClick={handleAdjustSubmit}
              disabled={adjustStockMutation.isPending || !adjustmentData.quantity}
              data-testid="button-submit-adjustment"
            >
              {adjustStockMutation.isPending && <Loader2 className="w-4 h-4 animate-spin me-2" />}
              {language === 'ar' ? 'تطبيق' : 'Apply'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={!!showHistoryDialog} onOpenChange={(open) => {
        if (!open) setShowHistoryDialog(null);
      }}>
        <DialogContent className="max-w-2xl" dir={language === 'ar' ? 'rtl' : 'ltr'}>
          <DialogHeader>
            <DialogTitle>
              {language === 'ar' ? 'سجل حركات المخزون' : 'Inventory Movement History'}
            </DialogTitle>
            <DialogDescription>
              {showHistoryDialog && (language === 'ar' ? showHistoryDialog.nameAr : showHistoryDialog.nameEn)}
            </DialogDescription>
          </DialogHeader>

          <div className="max-h-96 overflow-y-auto">
            {movements.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <History className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p>{language === 'ar' ? 'لا توجد حركات مسجلة' : 'No movements recorded'}</p>
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{language === 'ar' ? 'التاريخ' : 'Date'}</TableHead>
                    <TableHead>{language === 'ar' ? 'النوع' : 'Type'}</TableHead>
                    <TableHead>{language === 'ar' ? 'التغيير' : 'Change'}</TableHead>
                    <TableHead>{language === 'ar' ? 'من → إلى' : 'From → To'}</TableHead>
                    <TableHead>{language === 'ar' ? 'السبب' : 'Reason'}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {movements.map((movement) => (
                    <TableRow key={movement.id}>
                      <TableCell className="text-sm">
                        {new Date(movement.createdAt).toLocaleDateString(language === 'ar' ? 'ar-IQ' : 'en-US', {
                          year: 'numeric',
                          month: 'short',
                          day: 'numeric',
                          hour: '2-digit',
                          minute: '2-digit',
                        })}
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline">{getMovementTypeLabel(movement.movementType)}</Badge>
                      </TableCell>
                      <TableCell>
                        <span className={movement.quantityChange > 0 ? "text-green-600" : "text-red-600"}>
                          {movement.quantityChange > 0 ? '+' : ''}{movement.quantityChange}
                        </span>
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        {movement.previousQuantity} → {movement.newQuantity}
                      </TableCell>
                      <TableCell className="text-sm text-muted-foreground max-w-32 truncate">
                        {movement.reason || "-"}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowHistoryDialog(null)}>
              {language === 'ar' ? 'إغلاق' : 'Close'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={showImportDialog} onOpenChange={(open) => {
        if (!open) {
          setShowImportDialog(false);
          setCsvFile(null);
          setImportResults(null);
        }
      }}>
        <DialogContent className="max-w-lg" dir={language === 'ar' ? 'rtl' : 'ltr'}>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <FileSpreadsheet className="w-5 h-5" />
              {language === 'ar' ? 'استيراد المنتجات من CSV' : 'Import Products from CSV'}
            </DialogTitle>
            <DialogDescription>
              {language === 'ar' 
                ? 'قم برفع ملف CSV لإضافة أو تحديث المنتجات بشكل مجمع'
                : 'Upload a CSV file to add or update products in bulk'}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={handleDownloadTemplate} data-testid="button-download-template">
                <Download className="w-4 h-4 me-2" />
                {language === 'ar' ? 'تحميل قالب CSV' : 'Download CSV Template'}
              </Button>
            </div>

            <div className="border-2 border-dashed rounded-lg p-6 text-center">
              <input
                type="file"
                accept=".csv,.txt"
                onChange={handleFileChange}
                className="hidden"
                id="csv-file-input"
                data-testid="input-csv-file"
              />
              <label htmlFor="csv-file-input" className="cursor-pointer">
                <Upload className="w-8 h-8 mx-auto mb-2 text-muted-foreground" />
                <p className="text-sm text-muted-foreground">
                  {csvFile 
                    ? csvFile.name 
                    : (language === 'ar' ? 'اضغط لاختيار ملف CSV' : 'Click to select CSV file')}
                </p>
              </label>
            </div>

            {importResults && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-2">
                  <div className="flex items-center gap-2 p-2 bg-green-50 dark:bg-green-950 rounded">
                    <CheckCircle2 className="w-4 h-4 text-green-600" />
                    <span className="text-sm">
                      {language === 'ar' ? 'نجح:' : 'Success:'} {importResults.results.success}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 p-2 bg-red-50 dark:bg-red-950 rounded">
                    <XCircle className="w-4 h-4 text-red-600" />
                    <span className="text-sm">
                      {language === 'ar' ? 'فشل:' : 'Failed:'} {importResults.results.failed}
                    </span>
                  </div>
                </div>
                <div className="text-sm text-muted-foreground">
                  <p>{language === 'ar' ? 'جديد:' : 'Created:'} {importResults.results.created}</p>
                  <p>{language === 'ar' ? 'محدث:' : 'Updated:'} {importResults.results.updated}</p>
                </div>
                {importResults.results.errors.length > 0 && (
                  <div className="max-h-32 overflow-y-auto text-sm">
                    <p className="font-medium text-red-600 mb-1">
                      {language === 'ar' ? 'الأخطاء:' : 'Errors:'}
                    </p>
                    {importResults.results.errors.slice(0, 5).map((err, i) => (
                      <p key={i} className="text-red-500">
                        {language === 'ar' ? `صف ${err.row}: ${err.error}` : `Row ${err.row}: ${err.error}`}
                      </p>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          <DialogFooter className="gap-2">
            <Button
              variant="outline"
              onClick={() => {
                setShowImportDialog(false);
                setCsvFile(null);
                setImportResults(null);
              }}
            >
              {language === 'ar' ? 'إغلاق' : 'Close'}
            </Button>
            <Button
              onClick={handleImportSubmit}
              disabled={!csvFile || importMutation.isPending}
              data-testid="button-submit-import"
            >
              {importMutation.isPending && <Loader2 className="w-4 h-4 animate-spin me-2" />}
              {language === 'ar' ? 'استيراد' : 'Import'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

client/src/pages/AdminExternalPrices.tsx.content:
import { useEffect, useState } from "react";
import { useLocation, Link } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Plus, Edit, Trash2, Globe, DollarSign, ExternalLink, Loader2, RefreshCw } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { AdminNav } from "@/components/AdminNav";
import { Badge } from "@/components/ui/badge";
import type { MarketPrice, ExternalPriceSource } from "@shared/schema";

interface AdminUser {
  id: string;
  username: string;
  name: string;
  role: string;
}

interface ExchangeRateData {
  id?: string;
  rate: string;
  fromCurrency: string;
  toCurrency: string;
  lastUpdated?: string;
}

const sourceOptions = [
  { value: "newegg", labelAr: "نيو إيغ", labelEn: "Newegg", color: "bg-orange-500" },
  { value: "amazon", labelAr: "أمازون", labelEn: "Amazon", color: "bg-yellow-500" },
  { value: "aliexpress", labelAr: "علي إكسبريس", labelEn: "AliExpress", color: "bg-red-500" },
];

export default function AdminExternalPrices() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const { t, language } = useLanguage();
  const [showAddExternal, setShowAddExternal] = useState(false);
  const [showEditExternal, setShowEditExternal] = useState<ExternalPriceSource | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [editingRate, setEditingRate] = useState(false);
  const [newRate, setNewRate] = useState("");

  const [formData, setFormData] = useState({
    marketPriceId: "",
    source: "newegg",
    sourceProductUrl: "",
    sourceProductName: "",
    priceUSD: "",
  });

  const { data: currentAdmin, isLoading: authLoading, isError: authError } = useQuery<AdminUser>({
    queryKey: ['/api/admin/auth/me'],
    retry: false,
  });

  useEffect(() => {
    if (!authLoading && (authError || !currentAdmin)) {
      localStorage.removeItem("adminAuth");
      setLocation("/admin/login");
    }
  }, [authLoading, authError, currentAdmin, setLocation]);

  const { data: marketPrices = [] } = useQuery<MarketPrice[]>({
    queryKey: ['/api/admin/market-prices'],
    enabled: !!currentAdmin,
  });

  const { data: externalPrices = [], isLoading } = useQuery<ExternalPriceSource[]>({
    queryKey: ['/api/admin/external-prices'],
    enabled: !!currentAdmin,
  });

  const { data: exchangeRate } = useQuery<ExchangeRateData>({
    queryKey: ['/api/admin/exchange-rate'],
    enabled: !!currentAdmin,
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const response = await apiRequest('POST', '/api/admin/external-prices', data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/external-prices'] });
      setShowAddExternal(false);
      resetForm();
      toast({
        title: language === 'ar' ? "تم إضافة السعر الخارجي" : "External Price Added",
        description: language === 'ar' ? "تم إضافة مرجع السعر العالمي بنجاح" : "International price reference added successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في إضافة السعر" : "Failed to add price",
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof formData> }) => {
      const response = await apiRequest('PUT', `/api/admin/external-prices/${id}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/external-prices'] });
      setShowEditExternal(null);
      resetForm();
      toast({
        title: language === 'ar' ? "تم تحديث السعر" : "Price Updated",
        description: language === 'ar' ? "تم تحديث السعر الخارجي بنجاح" : "External price updated successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في تحديث السعر" : "Failed to update price",
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return await apiRequest('DELETE', `/api/admin/external-prices/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/external-prices'] });
      setDeleteId(null);
      toast({
        title: language === 'ar' ? "تم الحذف" : "Deleted",
        description: language === 'ar' ? "تم حذف السعر الخارجي بنجاح" : "External price deleted successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في حذف السعر" : "Failed to delete price",
        variant: "destructive",
      });
    },
  });

  const updateRateMutation = useMutation({
    mutationFn: async (rate: string) => {
      const response = await apiRequest('PUT', '/api/admin/exchange-rate', { rate });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/exchange-rate'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/external-prices'] });
      setEditingRate(false);
      toast({
        title: language === 'ar' ? "تم تحديث سعر الصرف" : "Exchange Rate Updated",
        description: language === 'ar' ? "تم تحديث سعر صرف الدولار بنجاح" : "USD exchange rate updated successfully",
      });
    },
    onError: () => {
      toast({
        title: language === 'ar' ? "خطأ" : "Error",
        description: language === 'ar' ? "فشل في تحديث سعر الصرف" : "Failed to update exchange rate",
        variant: "destructive",
      });
    },
  });

  const resetForm = () => {
    setFormData({
      marketPriceId: "",
      source: "newegg",
      sourceProductUrl: "",
      sourceProductName: "",
      priceUSD: "",
    });
  };

  const handleEditClick = (price: ExternalPriceSource) => {
    setFormData({
      marketPriceId: price.marketPriceId || "",
      source: price.source,
      sourceProductUrl: price.sourceProductUrl || "",
      sourceProductName: price.sourceProductName || "",
      priceUSD: price.priceUSD || "",
    });
    setShowEditExternal(price);
  };

  const handleSubmit = () => {
    if (showEditExternal) {
      updateMutation.mutate({ id: showEditExternal.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const getMarketPriceName = (id: string | null) => {
    if (!id) return language === 'ar' ? 'غير محدد' : 'Not specified';
    const price = marketPrices.find(p => p.id === id);
    if (!price) return language === 'ar' ? 'غير موجود' : 'Not found';
    return language === 'ar' ? price.nameAr : price.nameEn;
  };

  const formatPrice = (price: string) => {
    return new Intl.NumberFormat('ar-IQ').format(parseFloat(price));
  };

  const formatUSD = (price: string) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(parseFloat(price));
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin" />
      </div>
    );
  }

  if (!currentAdmin) {
    return null;
  }

  return (
    <div className="min-h-screen bg-background" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <AdminNav currentAdmin={currentAdmin} />

      <main className="max-w-7xl mx-auto px-4 py-8">
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="w-5 h-5" />
              {language === 'ar' ? 'سعر صرف الدولار' : 'USD Exchange Rate'}
            </CardTitle>
            <CardDescription>
              {language === 'ar' 
                ? 'سعر صرف الدولار الأمريكي مقابل الدينار العراقي المستخدم لتحويل الأسعار العالمية'
                : 'USD to IQD exchange rate used for converting international prices'
              }
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-4">
              <div className="flex-1">
                <div className="text-3xl font-bold" data-testid="text-exchange-rate">
                  $1 = {formatPrice(exchangeRate?.rate || "1310")} {language === 'ar' ? 'د.ع' : 'IQD'}
                </div>
                {exchangeRate?.lastUpdated && (
                  <p className="text-sm text-muted-foreground mt-1">
                    {language === 'ar' ? 'آخر تحديث:' : 'Last updated:'}{' '}
                    {new Date(exchangeRate.lastUpdated).toLocaleDateString(language === 'ar' ? 'ar-IQ' : 'en-US')}
                  </p>
                )}
              </div>
              {editingRate ? (
                <div className="flex items-center gap-2">
                  <Input
                    type="number"
                    value={newRate}
                    onChange={(e) => setNewRate(e.target.value)}
                    placeholder="1310"
                    className="w-32"
                    data-testid="input-exchange-rate"
                  />
                  <Button
                    size="sm"
                    onClick={() => updateRateMutation.mutate(newRate)}
                    disabled={updateRateMutation.isPending || !newRate}
                    data-testid="button-save-rate"
                  >
                    {updateRateMutation.isPending && <Loader2 className="w-4 h-4 animate-spin me-2" />}
                    {language === 'ar' ? 'حفظ' : 'Save'}
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setEditingRate(false)}
                  >
                    {language === 'ar' ? 'إلغاء' : 'Cancel'}
                  </Button>
                </div>
              ) : (
                <Button
                  variant="outline"
                  onClick={() => {
                    setNewRate(exchangeRate?.rate || "1310");
                    setEditingRate(true);
                  }}
                  data-testid="button-edit-rate"
                >
                  <RefreshCw className="w-4 h-4 me-2" />
                  {language === 'ar' ? 'تحديث السعر' : 'Update Rate'}
                </Button>
              )}
            </div>
          </CardContent>
        </Card>

        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-2xl font-bold flex items-center gap-2">
              <Globe className="w-6 h-6" />
              {language === 'ar' ? 'مراجع الأسعار العالمية' : 'International Price References'}
            </h2>
            <p className="text-muted-foreground">
              {language === 'ar' 
                ? 'أسعار المنتجات من المتاجر العالمية للمقارنة مع السوق المحلي'
                : 'Product prices from international stores for comparison with local market'
              }
            </p>
          </div>
          <Button onClick={() => setShowAddExternal(true)} data-testid="button-add-external">
            <Plus className="w-4 h-4 me-2" />
            {language === 'ar' ? 'إضافة سعر' : 'Add Price'}
          </Button>
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-8 h-8 animate-spin" />
          </div>
        ) : externalPrices.length === 0 ? (
          <Card>
            <CardContent className="py-12 text-center">
              <Globe className="w-12 h-12 mx-auto mb-4 text-muted-foreground opacity-50" />
              <p className="text-muted-foreground">
                {language === 'ar' ? 'لا توجد أسعار خارجية مسجلة بعد' : 'No external prices recorded yet'}
              </p>
              <Button variant="outline" className="mt-4" onClick={() => setShowAddExternal(true)}>
                <Plus className="w-4 h-4 me-2" />
                {language === 'ar' ? 'إضافة أول سعر' : 'Add First Price'}
              </Button>
            </CardContent>
          </Card>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {externalPrices.map(price => {
              const sourceInfo = sourceOptions.find(s => s.value === price.source.toLowerCase());
              return (
                <Card key={price.id} data-testid={`external-price-card-${price.id}`}>
                  <CardHeader className="pb-2">
                    <div className="flex items-start justify-between gap-2">
                      <div>
                        <CardTitle className="text-base flex items-center gap-2">
                          <span className={`w-2 h-2 rounded-full ${sourceInfo?.color || 'bg-gray-500'}`} />
                          {sourceInfo ? (language === 'ar' ? sourceInfo.labelAr : sourceInfo.labelEn) : price.source}
                        </CardTitle>
                        <CardDescription className="mt-1">
                          {getMarketPriceName(price.marketPriceId)}
                        </CardDescription>
                      </div>
                      <div className="flex gap-1">
                        <Button 
                          variant="ghost" 
                          size="icon" 
                          className="h-8 w-8"
                          onClick={() => handleEditClick(price)}
                          data-testid={`button-edit-${price.id}`}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button 
                          variant="ghost" 
                          size="icon" 
                          className="h-8 w-8 text-destructive"
                          onClick={() => setDeleteId(price.id)}
                          data-testid={`button-delete-${price.id}`}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    {price.sourceProductName && (
                      <p className="text-sm text-muted-foreground mb-2 line-clamp-1">
                        {price.sourceProductName}
                      </p>
                    )}
                    <div className="space-y-1">
                      <p className="text-2xl font-bold">
                        {price.priceUSD ? formatUSD(price.priceUSD) : '-'}
                      </p>
                      {price.priceIQD && (
                        <p className="text-sm text-muted-foreground">
                          ≈ {formatPrice(price.priceIQD)} {language === 'ar' ? 'د.ع' : 'IQD'}
                        </p>
                      )}
                    </div>
                    {price.sourceProductUrl && (
                      <a
                        href={price.sourceProductUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-sm text-primary hover:underline mt-3"
                        data-testid={`link-source-${price.id}`}
                      >
                        <ExternalLink className="w-3 h-3" />
                        {language === 'ar' ? 'عرض المنتج' : 'View Product'}
                      </a>
                    )}
                    <p className="text-xs text-muted-foreground mt-2 border-t pt-2">
                      {language === 'ar' ? 'آخر تحديث:' : 'Last update:'}{' '}
                      {new Date(price.lastUpdated).toLocaleDateString(language === 'ar' ? 'ar-IQ' : 'en-US')}
                    </p>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </main>

      <Dialog open={showAddExternal || !!showEditExternal} onOpenChange={(open) => {
        if (!open) {
          setShowAddExternal(false);
          setShowEditExternal(null);
          resetForm();
        }
      }}>
        <DialogContent className="max-w-md" dir={language === 'ar' ? 'rtl' : 'ltr'}>
          <DialogHeader>
            <DialogTitle>
              {showEditExternal 
                ? (language === 'ar' ? 'تعديل السعر الخارجي' : 'Edit External Price')
                : (language === 'ar' ? 'إضافة سعر خارجي' : 'Add External Price')
              }
            </DialogTitle>
            <DialogDescription>
              {language === 'ar' 
                ? 'أدخل تفاصيل السعر من المتجر العالمي'
                : 'Enter price details from the international store'
              }
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>{language === 'ar' ? 'المنتج المحلي' : 'Local Product'}</Label>
              <Select
                value={formData.marketPriceId}
                onValueChange={(value) => setFormData(prev => ({ ...prev, marketPriceId: value }))}
              >
                <SelectTrigger data-testid="select-market-price">
                  <SelectValue placeholder={language === 'ar' ? 'اختر المنتج' : 'Select product'} />
                </SelectTrigger>
                <SelectContent>
                  {marketPrices.map(price => (
                    <SelectItem key={price.id} value={price.id}>
                      {language === 'ar' ? price.nameAr : price.nameEn} - {price.brand} {price.capacity}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'المتجر' : 'Store'}</Label>
              <Select
                value={formData.source}
                onValueChange={(value) => setFormData(prev => ({ ...prev, source: value }))}
              >
                <SelectTrigger data-testid="select-source">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {sourceOptions.map(source => (
                    <SelectItem key={source.value} value={source.value}>
                      <div className="flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full ${source.color}`} />
                        {language === 'ar' ? source.labelAr : source.labelEn}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'اسم المنتج (اختياري)' : 'Product Name (Optional)'}</Label>
              <Input
                value={formData.sourceProductName}
                onChange={(e) => setFormData(prev => ({ ...prev, sourceProductName: e.target.value }))}
                placeholder={language === 'ar' ? 'اسم المنتج في المتجر' : 'Product name in store'}
                data-testid="input-product-name"
              />
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'رابط المنتج (اختياري)' : 'Product URL (Optional)'}</Label>
              <Input
                value={formData.sourceProductUrl}
                onChange={(e) => setFormData(prev => ({ ...prev, sourceProductUrl: e.target.value }))}
                placeholder="https://..."
                dir="ltr"
                data-testid="input-product-url"
              />
            </div>

            <div className="space-y-2">
              <Label>{language === 'ar' ? 'السعر بالدولار ($)' : 'Price in USD ($)'}</Label>
              <Input
                type="number"
                value={formData.priceUSD}
                onChange={(e) => setFormData(prev => ({ ...prev, priceUSD: e.target.value }))}
                placeholder="0.00"
                dir="ltr"
                data-testid="input-price-usd"
              />
              {formData.priceUSD && exchangeRate?.rate && (
                <p className="text-sm text-muted-foreground">
                  ≈ {formatPrice((parseFloat(formData.priceUSD) * parseFloat(exchangeRate.rate)).toFixed(0))} {language === 'ar' ? 'د.ع' : 'IQD'}
                </p>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowAddExternal(false);
                setShowEditExternal(null);
                resetForm();
              }}
            >
              {language === 'ar' ? 'إلغاء' : 'Cancel'}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={createMutation.isPending || updateMutation.isPending || !formData.marketPriceId || !formData.priceUSD}
              data-testid="button-submit-external"
            >
              {(createMutation.isPending || updateMutation.isPending) && (
                <Loader2 className="w-4 h-4 animate-spin me-2" />
              )}
              {showEditExternal 
                ? (language === 'ar' ? 'تحديث' : 'Update')
                : (language === 'ar' ? 'إضافة' : 'Add')
              }
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent dir={language === 'ar' ? 'rtl' : 'ltr'}>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {language === 'ar' ? 'تأكيد الحذف' : 'Confirm Delete'}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {language === 'ar' 
                ? 'هل أنت متأكد من حذف هذا السعر؟ لا يمكن التراجع عن هذا الإجراء.'
                : 'Are you sure you want to delete this price? This action cannot be undone.'
              }
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{language === 'ar' ? 'إلغاء' : 'Cancel'}</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deleteId && deleteMutation.mutate(deleteId)}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleteMutation.isPending && <Loader2 className="w-4 h-4 animate-spin me-2" />}
              {language === 'ar' ? 'حذف' : 'Delete'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

