import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLanguage } from "@/contexts/LanguageContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { 
  BarChart3, 
  DollarSign,
  ShoppingCart,
  TrendingUp,
  Loader2,
  Calendar
} from "lucide-react";
import { startOfDay, startOfWeek, startOfMonth, startOfYear, isAfter } from "date-fns";

interface Order {
  id: string;
  orderNumber: string;
  customerName: string;
  total: string;
  paymentMethod: string;
  orderType: string | null;
  status: string;
  createdAt: string;
  items: any[];
}

interface SalesUser {
  id: string;
  permissions: {
    canViewReports: number;
  };
}

interface SalesReportsProps {
  user: SalesUser;
}

export default function SalesReports({ user }: SalesReportsProps) {
  const { language } = useLanguage();
  const [dateRange, setDateRange] = useState<'today' | 'week' | 'month' | 'year' | 'all'>('today');
  const [orderTypeFilter, setOrderTypeFilter] = useState<'all' | 'online' | 'walk-in'>('all');

  const { data: orders = [], isLoading } = useQuery<Order[]>({
    queryKey: ['/api/orders'],
  });

  if (!user.permissions.canViewReports) {
    return (
      <div className="flex items-center justify-center h-96">
        <p className="text-muted-foreground">
          {language === 'ar' ? 'ليس لديك صلاحية عرض التقارير' : 'You do not have access to reports'}
        </p>
      </div>
    );
  }

  const getDateRangeStart = () => {
    const now = new Date();
    switch (dateRange) {
      case 'today': return startOfDay(now);
      case 'week': return startOfWeek(now, { weekStartsOn: 0 });
      case 'month': return startOfMonth(now);
      case 'year': return startOfYear(now);
      default: return new Date(0);
    }
  };

  const filteredOrders = orders.filter(order => {
    const orderDate = new Date(order.createdAt);
    const rangeStart = getDateRangeStart();

    if (!isAfter(orderDate, rangeStart) && dateRange !== 'all') return false;

    if (orderTypeFilter !== 'all') {
      const orderType = order.orderType || 'online';
      if (orderTypeFilter === 'walk-in' && orderType !== 'walk-in') return false;
      if (orderTypeFilter === 'online' && orderType !== 'online') return false;
    }

    return true;
  });

  const totalRevenue = filteredOrders.reduce((sum, o) => sum + parseFloat(o.total || '0'), 0);
  const orderCount = filteredOrders.length;
  const avgOrderValue = orderCount > 0 ? totalRevenue / orderCount : 0;
  const walkInOrders = filteredOrders.filter(o => o.orderType === 'walk-in').length;
  const onlineOrders = filteredOrders.filter(o => o.orderType !== 'walk-in').length;

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('ar-IQ').format(price);
  };

  const getPaymentMethodLabel = (method: string) => {
    const labels: Record<string, { ar: string; en: string }> = {
      'cash': { ar: 'نقداً', en: 'Cash' },
      'card': { ar: 'بطاقة', en: 'Card' },
      'zaincash': { ar: 'زين كاش', en: 'ZainCash' },
      'qicard': { ar: 'كي كارد', en: 'QiCard' },
      'cod': { ar: 'عند الاستلام', en: 'COD' },
    };
    return language === 'ar' ? labels[method]?.ar || method : labels[method]?.en || method;
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <BarChart3 className="h-6 w-6" />
          {language === 'ar' ? 'تقارير المبيعات' : 'Sales Reports'}
        </h2>
        <div className="flex flex-wrap gap-2">
          <Select value={dateRange} onValueChange={(v: any) => setDateRange(v)}>
            <SelectTrigger className="w-40" data-testid="select-date-range">
              <Calendar className="h-4 w-4 me-2" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="today">{language === 'ar' ? 'اليوم' : 'Today'}</SelectItem>
              <SelectItem value="week">{language === 'ar' ? 'هذا الأسبوع' : 'This Week'}</SelectItem>
              <SelectItem value="month">{language === 'ar' ? 'هذا الشهر' : 'This Month'}</SelectItem>
              <SelectItem value="year">{language === 'ar' ? 'هذا العام' : 'This Year'}</SelectItem>
              <SelectItem value="all">{language === 'ar' ? 'الكل' : 'All Time'}</SelectItem>
            </SelectContent>
          </Select>
          <Select value={orderTypeFilter} onValueChange={(v: any) => setOrderTypeFilter(v)}>
            <SelectTrigger className="w-40" data-testid="select-order-type">
              <ShoppingCart className="h-4 w-4 me-2" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">{language === 'ar' ? 'جميع الطلبات' : 'All Orders'}</SelectItem>
              <SelectItem value="walk-in">{language === 'ar' ? 'في المتجر' : 'Walk-in'}</SelectItem>
              <SelectItem value="online">{language === 'ar' ? 'أونلاين' : 'Online'}</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-green-500/10 rounded-lg">
                <DollarSign className="h-5 w-5 text-green-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'إجمالي الإيرادات' : 'Total Revenue'}
                </p>
                <p className="text-xl font-bold">{formatPrice(totalRevenue)} IQD</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-blue-500/10 rounded-lg">
                <ShoppingCart className="h-5 w-5 text-blue-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'عدد الطلبات' : 'Order Count'}
                </p>
                <p className="text-xl font-bold">{orderCount}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-purple-500/10 rounded-lg">
                <TrendingUp className="h-5 w-5 text-purple-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'متوسط الطلب' : 'Avg. Order'}
                </p>
                <p className="text-xl font-bold">{formatPrice(avgOrderValue)} IQD</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-orange-500/10 rounded-lg">
                <ShoppingCart className="h-5 w-5 text-orange-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'في المتجر / أونلاين' : 'Walk-in / Online'}
                </p>
                <p className="text-xl font-bold">{walkInOrders} / {onlineOrders}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{language === 'ar' ? 'سجل الطلبات' : 'Order History'}</CardTitle>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="flex items-center justify-center h-64">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredOrders.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              {language === 'ar' ? 'لا توجد طلبات في هذه الفترة' : 'No orders in this period'}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-start p-3">{language === 'ar' ? 'رقم الطلب' : 'Order #'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'العميل' : 'Customer'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'النوع' : 'Type'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'الدفع' : 'Payment'}</th>
                    <th className="text-end p-3">{language === 'ar' ? 'المبلغ' : 'Amount'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'التاريخ' : 'Date'}</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredOrders.slice(0, 50).map(order => (
                    <tr key={order.id} className="border-b hover:bg-muted/50">
                      <td className="p-3 font-mono">{order.orderNumber}</td>
                      <td className="p-3">{order.customerName}</td>
                      <td className="p-3">
                        <Badge variant={order.orderType === 'walk-in' ? 'default' : 'secondary'}>
                          {order.orderType === 'walk-in' 
                            ? (language === 'ar' ? 'في المتجر' : 'Walk-in')
                            : (language === 'ar' ? 'أونلاين' : 'Online')
                          }
                        </Badge>
                      </td>
                      <td className="p-3">{getPaymentMethodLabel(order.paymentMethod)}</td>
                      <td className="p-3 text-end font-bold">{formatPrice(parseFloat(order.total))} IQD</td>
                      <td className="p-3 text-muted-foreground">
                        {new Date(order.createdAt).toLocaleDateString('ar-IQ')}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {filteredOrders.length > 50 && (
                <p className="text-center text-muted-foreground mt-4">
                  {language === 'ar' 
                    ? `عرض أول 50 من ${filteredOrders.length} طلب` 
                    : `Showing first 50 of ${filteredOrders.length} orders`}
                </p>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/SalesInventory.tsx.content:
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLanguage } from "@/contexts/LanguageContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { 
  Search, 
  Package, 
  AlertTriangle,
  Loader2,
} from "lucide-react";
import type { Product } from "@shared/schema";

interface SalesUser {
  id: string;
  permissions: {
    canInventory: number;
  };
}

interface SalesInventoryProps {
  user: SalesUser;
}

export default function SalesInventory({ user }: SalesInventoryProps) {
  const { language } = useLanguage();
  const [searchQuery, setSearchQuery] = useState("");

  const { data: products = [], isLoading } = useQuery<Product[]>({
    queryKey: ['/api/products'],
  });

  if (!user.permissions.canInventory) {
    return (
      <div className="flex items-center justify-center h-96">
        <p className="text-muted-foreground">
          {language === 'ar' ? 'ليس لديك صلاحية الوصول للمخزون' : 'You do not have access to Inventory'}
        </p>
      </div>
    );
  }

  const filteredProducts = products.filter(p => {
    const name = language === 'ar' ? p.nameAr : (p.nameEn || p.nameAr);
    const sku = p.sku || '';
    return name.toLowerCase().includes(searchQuery.toLowerCase()) ||
           sku.toLowerCase().includes(searchQuery.toLowerCase());
  });

  const lowStockProducts = products.filter(p => 
    (p.stockQuantity || 0) <= (p.lowStockThreshold || 5)
  );

  const totalStock = products.reduce((sum, p) => sum + (p.stockQuantity || 0), 0);
  const outOfStock = products.filter(p => (p.stockQuantity || 0) === 0).length;

  const formatNumber = (num: number) => {
    return new Intl.NumberFormat('ar-IQ').format(num);
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-primary/10 rounded-lg">
                <Package className="h-5 w-5 text-primary" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'إجمالي المنتجات' : 'Total Products'}
                </p>
                <p className="text-2xl font-bold">{formatNumber(products.length)}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-green-500/10 rounded-lg">
                <Package className="h-5 w-5 text-green-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'إجمالي المخزون' : 'Total Stock'}
                </p>
                <p className="text-2xl font-bold">{formatNumber(totalStock)}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-yellow-500/10 rounded-lg">
                <AlertTriangle className="h-5 w-5 text-yellow-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'مخزون منخفض' : 'Low Stock'}
                </p>
                <p className="text-2xl font-bold">{formatNumber(lowStockProducts.length)}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-red-500/10 rounded-lg">
                <Package className="h-5 w-5 text-red-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">
                  {language === 'ar' ? 'نفد المخزون' : 'Out of Stock'}
                </p>
                <p className="text-2xl font-bold">{formatNumber(outOfStock)}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {lowStockProducts.length > 0 && (
        <Card className="border-yellow-500/50">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-yellow-600">
              <AlertTriangle className="h-5 w-5" />
              {language === 'ar' ? 'تنبيه: منتجات بمخزون منخفض' : 'Alert: Low Stock Products'}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex flex-wrap gap-2">
              {lowStockProducts.slice(0, 10).map(p => (
                <Badge key={p.id} variant="outline" className="bg-yellow-50">
                  {language === 'ar' ? p.nameAr : (p.nameEn || p.nameAr)}
                  <span className="ms-2 text-yellow-600">({p.stockQuantity || 0})</span>
                </Badge>
              ))}
              {lowStockProducts.length > 10 && (
                <Badge variant="secondary">
                  +{lowStockProducts.length - 10} {language === 'ar' ? 'المزيد' : 'more'}
                </Badge>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between flex-wrap gap-4">
            <CardTitle>
              {language === 'ar' ? 'قائمة المنتجات' : 'Product List'}
            </CardTitle>
            <div className="relative w-full max-w-sm">
              <Search className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder={language === 'ar' ? 'البحث...' : 'Search...'}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pr-10"
                data-testid="input-inventory-search"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="flex items-center justify-center h-64">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-start p-3">{language === 'ar' ? 'المنتج' : 'Product'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'SKU' : 'SKU'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'الفئة' : 'Category'}</th>
                    <th className="text-center p-3">{language === 'ar' ? 'المخزون' : 'Stock'}</th>
                    <th className="text-center p-3">{language === 'ar' ? 'الحد الأدنى' : 'Min'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'الحالة' : 'Status'}</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredProducts.map(product => {
                    const stock = product.stockQuantity || 0;
                    const threshold = product.lowStockThreshold || 5;
                    let status: 'ok' | 'low' | 'out' = 'ok';
                    if (stock === 0) status = 'out';
                    else if (stock <= threshold) status = 'low';

                    return (
                      <tr key={product.id} className="border-b hover:bg-muted/50">
                        <td className="p-3">
                          <div className="flex items-center gap-3">
                            {product.image && (
                              <img 
                                src={product.image} 
                                alt={product.nameAr}
                                className="w-10 h-10 object-cover rounded"
                              />
                            )}
                            <span className="font-medium">
                              {language === 'ar' ? product.nameAr : (product.nameEn || product.nameAr)}
                            </span>
                          </div>
                        </td>
                        <td className="p-3 text-muted-foreground">{product.sku || '-'}</td>
                        <td className="p-3">{product.category}</td>
                        <td className="p-3 text-center font-bold">{formatNumber(stock)}</td>
                        <td className="p-3 text-center text-muted-foreground">{threshold}</td>
                        <td className="p-3">
                          {status === 'out' && (
                            <Badge variant="destructive">
                              {language === 'ar' ? 'نفد' : 'Out'}
                            </Badge>
                          )}
                          {status === 'low' && (
                            <Badge variant="outline" className="border-yellow-500 text-yellow-600">
                              {language === 'ar' ? 'منخفض' : 'Low'}
                            </Badge>
                          )}
                          {status === 'ok' && (
                            <Badge variant="outline" className="border-green-500 text-green-600">
                              {language === 'ar' ? 'متوفر' : 'OK'}
                            </Badge>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/SalesPortal.tsx.content:
import { useEffect, useState, useMemo } from "react";
import { useLocation, Link } from "wouter";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useLanguage } from "@/contexts/LanguageContext";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { 
  ShoppingCart, 
  Package, 
  Users, 
  BarChart3, 
  LogOut, 
  Loader2,
  Menu,
  X,
  LayoutDashboard,
  Store,
  Settings,
  Bell,
  ChevronDown
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import SalesDashboard from "./SalesDashboard";
import SalesPOS from "./SalesPOS";
import SalesInventory from "./SalesInventory";
import SalesUsers from "./SalesUsers";
import SalesReports from "./SalesReports";

interface SalesUser {
  id: string;
  username: string;
  name: string;
  role: string;
  permissions: {
    canPos: number;
    canInventory: number;
    canManageUsers: number;
    canViewReports: number;
    canApplyDiscount: number;
  };
}

export default function SalesPortal() {
  const { language } = useLanguage();
  const [location, setLocation] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const { data: currentUser, isLoading, error } = useQuery<SalesUser>({
    queryKey: ['/api/sales/auth/me'],
    retry: false,
  });

  const logoutMutation = useMutation({
    mutationFn: async () => {
      const res = await apiRequest('POST', '/api/sales/auth/logout', {});
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/sales/auth/me'] });
      setLocation("/sales/login");
    },
  });

  useEffect(() => {
    if (!isLoading && (error || !currentUser)) {
      setLocation("/sales/login");
    }
  }, [isLoading, error, currentUser, setLocation]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-primary/5 via-background to-primary/10">
        <div className="text-center space-y-4">
          <div className="h-16 w-16 rounded-2xl bg-primary/10 flex items-center justify-center mx-auto animate-pulse">
            <Store className="h-8 w-8 text-primary" />
          </div>
          <Loader2 className="h-6 w-6 animate-spin mx-auto text-primary" />
          <p className="text-muted-foreground">
            {language === 'ar' ? 'جاري التحميل...' : 'Loading...'}
          </p>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return null;
  }

  const navItems = [
    { 
      path: "/sales", 
      exactMatch: true,
      label: language === 'ar' ? 'لوحة التحكم' : 'Dashboard', 
      icon: LayoutDashboard,
      permission: true,
      color: 'text-primary',
    },
    { 
      path: "/sales/pos", 
      label: language === 'ar' ? 'نقطة البيع' : 'Point of Sale', 
      icon: ShoppingCart,
      permission: currentUser.permissions.canPos,
      color: 'text-green-500',
    },
    { 
      path: "/sales/inventory", 
      label: language === 'ar' ? 'المخزون' : 'Inventory', 
      icon: Package,
      permission: currentUser.permissions.canInventory,
      color: 'text-blue-500',
    },
    { 
      path: "/sales/reports", 
      label: language === 'ar' ? 'التقارير' : 'Reports', 
      icon: BarChart3,
      permission: currentUser.permissions.canViewReports,
      color: 'text-purple-500',
    },
    { 
      path: "/sales/users", 
      label: language === 'ar' ? 'المستخدمين' : 'Users', 
      icon: Users,
      permission: currentUser.permissions.canManageUsers,
      color: 'text-orange-500',
    },
  ].filter(item => item.permission);

  const isActive = (path: string, exactMatch?: boolean) => {
    if (exactMatch) {
      return location === path || location === path + '/';
    }
    return location === path || location.startsWith(path + '/');
  };

  const currentPage = navItems.find(item => isActive(item.path, item.exactMatch)) || navItems[0];

  return (
    <div className="min-h-screen bg-muted/30" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      {/* Enhanced Header */}
      <header className="sticky top-0 z-50 bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60 border-b shadow-sm">
        <div className="container mx-auto px-4">
          <div className="flex items-center justify-between h-16">
            {/* Logo & Mobile Menu */}
            <div className="flex items-center gap-3">
              <Button
                variant="ghost"
                size="icon"
                className="md:hidden"
                onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                data-testid="button-mobile-menu"
              >
                {mobileMenuOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
              </Button>
              <Link href="/sales">
                <div className="flex items-center gap-3 cursor-pointer group">
                  <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-primary to-primary/70 flex items-center justify-center shadow-md group-hover:shadow-lg transition-shadow">
                    <Store className="h-5 w-5 text-primary-foreground" />
                  </div>
                  <div className="hidden sm:block">
                    <h1 className="font-bold text-lg leading-tight">
                      {language === 'ar' ? 'بوابة المبيعات' : 'Sales Portal'}
                    </h1>
                    <p className="text-xs text-muted-foreground">
                      {language === 'ar' ? 'العين لتجارة الحاسبات' : 'Al-Ain Computers'}
                    </p>
                  </div>
                </div>
              </Link>
            </div>

            {/* Desktop Navigation */}
            <nav className="hidden md:flex items-center gap-1 bg-muted/50 rounded-lg p-1">
              {navItems.map((item) => (
                <Link key={item.path} href={item.path}>
                  <Button
                    variant={isActive(item.path, item.exactMatch) ? "default" : "ghost"}
                    size="sm"
                    className={`gap-2 transition-all ${
                      isActive(item.path, item.exactMatch) 
                        ? 'shadow-sm' 
                        : 'hover:bg-background'
                    }`}
                    data-testid={`nav-${item.path.replace('/sales/', '') || 'dashboard'}`}
                  >
                    <item.icon className={`h-4 w-4 ${!isActive(item.path, item.exactMatch) ? item.color : ''}`} />
                    <span className="hidden lg:inline">{item.label}</span>
                  </Button>
                </Link>
              ))}
            </nav>

            {/* User Menu & Actions */}
            <div className="flex items-center gap-2">
              {/* Notifications */}
              <Button variant="ghost" size="icon" className="relative" data-testid="button-notifications">
                <Bell className="h-5 w-5" />
                <span className="absolute top-1 end-1 h-2 w-2 rounded-full bg-red-500" />
              </Button>

              {/* User Dropdown */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" className="gap-2 px-2" data-testid="button-user-menu">
                    <div className="h-8 w-8 rounded-full bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center border">
                      <span className="text-sm font-bold text-primary">
                        {currentUser.name.charAt(0).toUpperCase()}
                      </span>
                    </div>
                    <div className="hidden sm:block text-start">
                      <p className="text-sm font-medium leading-tight">{currentUser.name}</p>
                      <p className="text-xs text-muted-foreground">
                        {currentUser.role === 'admin' 
                          ? (language === 'ar' ? 'مدير' : 'Admin')
                          : (language === 'ar' ? 'موظف' : 'Staff')
                        }
                      </p>
                    </div>
                    <ChevronDown className="h-4 w-4 text-muted-foreground hidden sm:block" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-56">
                  <DropdownMenuLabel>
                    <div className="flex flex-col">
                      <span>{currentUser.name}</span>
                      <span className="text-xs font-normal text-muted-foreground">@{currentUser.username}</span>
                    </div>
                  </DropdownMenuLabel>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem className="gap-2">
                    <Settings className="h-4 w-4" />
                    {language === 'ar' ? 'الإعدادات' : 'Settings'}
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem 
                    className="gap-2 text-destructive focus:text-destructive"
                    onClick={() => logoutMutation.mutate()}
                    disabled={logoutMutation.isPending}
                  >
                    <LogOut className="h-4 w-4" />
                    {language === 'ar' ? 'تسجيل الخروج' : 'Logout'}
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>
        </div>

        {/* Mobile Navigation Menu */}
        {mobileMenuOpen && (
          <div className="md:hidden border-t bg-background animate-in slide-in-from-top-2">
            <nav className="container mx-auto px-4 py-3 space-y-1">
              {navItems.map((item) => (
                <Link key={item.path} href={item.path}>
                  <Button
                    variant={isActive(item.path, item.exactMatch) ? "secondary" : "ghost"}
                    className="w-full justify-start gap-3"
                    onClick={() => setMobileMenuOpen(false)}
                  >
                    <div className={`h-8 w-8 rounded-lg flex items-center justify-center ${
                      isActive(item.path, item.exactMatch) ? 'bg-primary/10' : 'bg-muted'
                    }`}>
                      <item.icon className={`h-4 w-4 ${item.color}`} />
                    </div>
                    <span>{item.label}</span>
                  </Button>
                </Link>
              ))}
            </nav>
          </div>
        )}
      </header>

      {/* Page Content */}
      <main className="container mx-auto px-4 py-6">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-muted-foreground mb-6">
          <Link href="/sales">
            <span className="hover:text-primary transition-colors cursor-pointer">
              {language === 'ar' ? 'بوابة المبيعات' : 'Sales Portal'}
            </span>
          </Link>
          <span>/</span>
          <span className="text-foreground font-medium flex items-center gap-1.5">
            <currentPage.icon className={`h-4 w-4 ${currentPage.color}`} />
            {currentPage.label}
          </span>
        </div>

        {/* Render Active Page */}
        {(location === "/sales" || location === "/sales/") && <SalesDashboard user={currentUser} />}
        {location === "/sales/pos" && <SalesPOS user={currentUser} />}
        {location === "/sales/inventory" && <SalesInventory user={currentUser} />}
        {location === "/sales/reports" && <SalesReports user={currentUser} />}
        {location === "/sales/users" && <SalesUsers user={currentUser} />}
      </main>
    </div>
  );
}

client/src/pages/SalesLogin.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useLanguage } from "@/contexts/LanguageContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { ShoppingCart, User, Lock, Loader2 } from "lucide-react";

export default function SalesLogin() {
  const { language } = useLanguage();
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const { data: currentUser, isLoading: authLoading } = useQuery({
    queryKey: ['/api/sales/auth/me'],
    retry: false,
  });

  const loginMutation = useMutation({
    mutationFn: async (data: { username: string; password: string }) => {
      const res = await apiRequest('POST', '/api/sales/auth/login', data);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/sales/auth/me'] });
      toast({
        title: language === 'ar' ? 'تم تسجيل الدخول بنجاح' : 'Login successful',
      });
      setLocation("/sales");
    },
    onError: (error: any) => {
      toast({
        title: language === 'ar' ? 'فشل تسجيل الدخول' : 'Login failed',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  if (currentUser) {
    setLocation("/sales");
    return null;
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    loginMutation.mutate({ username, password });
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-muted/30 p-4" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <Card className="w-full max-w-md">
        <CardHeader className="text-center space-y-4">
          <div className="mx-auto w-16 h-16 bg-primary rounded-full flex items-center justify-center">
            <ShoppingCart className="h-8 w-8 text-primary-foreground" />
          </div>
          <CardTitle className="text-2xl">
            {language === 'ar' ? 'بوابة المبيعات' : 'Sales Portal'}
          </CardTitle>
          <p className="text-muted-foreground text-sm">
            {language === 'ar' ? 'تسجيل الدخول للوصول إلى نقطة البيع' : 'Login to access Point of Sale'}
          </p>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="username" className="flex items-center gap-2">
                <User className="h-4 w-4" />
                {language === 'ar' ? 'اسم المستخدم' : 'Username'}
              </Label>
              <Input
                id="username"
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder={language === 'ar' ? 'أدخل اسم المستخدم' : 'Enter username'}
                required
                data-testid="input-sales-username"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password" className="flex items-center gap-2">
                <Lock className="h-4 w-4" />
                {language === 'ar' ? 'كلمة المرور' : 'Password'}
              </Label>
              <Input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder={language === 'ar' ? 'أدخل كلمة المرور' : 'Enter password'}
                required
                data-testid="input-sales-password"
              />
            </div>
            <Button 
              type="submit" 
              className="w-full" 
              disabled={loginMutation.isPending}
              data-testid="button-sales-login"
            >
              {loginMutation.isPending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                language === 'ar' ? 'تسجيل الدخول' : 'Login'
              )}
            </Button>
          </form>
          <div className="mt-4 text-center text-sm text-muted-foreground">
            {language === 'ar' 
              ? 'للوصول إلى لوحة الإدارة الرئيسية، استخدم' 
              : 'For main admin dashboard, use'}
            {' '}
            <a href="/admin/login" className="text-primary hover:underline">
              {language === 'ar' ? 'تسجيل دخول المدير' : 'Admin Login'}
            </a>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

