import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useLanguage } from "@/contexts/LanguageContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { 
  Plus, 
  Pencil, 
  Trash2, 
  Users,
  Loader2,
  Shield,
  ShoppingCart,
  Package,
  BarChart3,
  Percent
} from "lucide-react";

interface SalesUser {
  id: string;
  username: string;
  name: string;
  role: string;
  canPos: number;
  canInventory: number;
  canManageUsers: number;
  canViewReports: number;
  canApplyDiscount: number;
  isActive: number;
  createdAt: string;
}

interface CurrentUser {
  id: string;
  permissions: {
    canManageUsers: number;
  };
}

interface SalesUsersProps {
  user: CurrentUser;
}

export default function SalesUsers({ user }: SalesUsersProps) {
  const { language } = useLanguage();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<SalesUser | null>(null);
  const [formData, setFormData] = useState({
    username: "",
    password: "",
    name: "",
    role: "sales",
    canPos: 1,
    canInventory: 0,
    canManageUsers: 0,
    canViewReports: 0,
    canApplyDiscount: 0,
    isActive: 1,
  });

  const { data: users = [], isLoading } = useQuery<SalesUser[]>({
    queryKey: ['/api/sales/users'],
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const res = await apiRequest('POST', '/api/sales/users', data);
      return res.json();
    },
    onSuccess: () => {
      toast({ title: language === 'ar' ? 'تم إنشاء المستخدم' : 'User created' });
      queryClient.invalidateQueries({ queryKey: ['/api/sales/users'] });
      setDialogOpen(false);
      resetForm();
    },
    onError: (error: any) => {
      toast({ title: error.message, variant: 'destructive' });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof formData> }) => {
      const res = await apiRequest('PUT', `/api/sales/users/${id}`, data);
      return res.json();
    },
    onSuccess: () => {
      toast({ title: language === 'ar' ? 'تم تحديث المستخدم' : 'User updated' });
      queryClient.invalidateQueries({ queryKey: ['/api/sales/users'] });
      setDialogOpen(false);
      setEditingUser(null);
      resetForm();
    },
    onError: (error: any) => {
      toast({ title: error.message, variant: 'destructive' });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await apiRequest('DELETE', `/api/sales/users/${id}`, {});
      return res.json();
    },
    onSuccess: () => {
      toast({ title: language === 'ar' ? 'تم حذف المستخدم' : 'User deleted' });
      queryClient.invalidateQueries({ queryKey: ['/api/sales/users'] });
    },
    onError: (error: any) => {
      toast({ title: error.message, variant: 'destructive' });
    },
  });

  const resetForm = () => {
    setFormData({
      username: "",
      password: "",
      name: "",
      role: "sales",
      canPos: 1,
      canInventory: 0,
      canManageUsers: 0,
      canViewReports: 0,
      canApplyDiscount: 0,
      isActive: 1,
    });
  };

  const openEditDialog = (u: SalesUser) => {
    setEditingUser(u);
    setFormData({
      username: u.username,
      password: "",
      name: u.name,
      role: u.role,
      canPos: u.canPos,
      canInventory: u.canInventory,
      canManageUsers: u.canManageUsers,
      canViewReports: u.canViewReports,
      canApplyDiscount: u.canApplyDiscount,
      isActive: u.isActive,
    });
    setDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      const updateData = { ...formData };
      if (!updateData.password) delete (updateData as any).password;
      updateMutation.mutate({ id: editingUser.id, data: updateData });
    } else {
      createMutation.mutate(formData);
    }
  };

  if (!user.permissions.canManageUsers) {
    return (
      <div className="flex items-center justify-center h-96">
        <p className="text-muted-foreground">
          {language === 'ar' ? 'ليس لديك صلاحية إدارة المستخدمين' : 'You do not have access to manage users'}
        </p>
      </div>
    );
  }

  const permissionIcons = {
    canPos: ShoppingCart,
    canInventory: Package,
    canManageUsers: Users,
    canViewReports: BarChart3,
    canApplyDiscount: Percent,
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <Users className="h-6 w-6" />
          {language === 'ar' ? 'إدارة المستخدمين' : 'User Management'}
        </h2>
        <Dialog open={dialogOpen} onOpenChange={(open) => {
          setDialogOpen(open);
          if (!open) {
            setEditingUser(null);
            resetForm();
          }
        }}>
          <DialogTrigger asChild>
            <Button data-testid="button-add-user">
              <Plus className="h-4 w-4 me-2" />
              {language === 'ar' ? 'إضافة مستخدم' : 'Add User'}
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>
                {editingUser 
                  ? (language === 'ar' ? 'تعديل مستخدم' : 'Edit User')
                  : (language === 'ar' ? 'إضافة مستخدم جديد' : 'Add New User')
                }
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>{language === 'ar' ? 'اسم المستخدم' : 'Username'}</Label>
                  <Input
                    value={formData.username}
                    onChange={(e) => setFormData(prev => ({ ...prev, username: e.target.value }))}
                    required
                    data-testid="input-new-username"
                  />
                </div>
                <div className="space-y-2">
                  <Label>
                    {language === 'ar' ? 'كلمة المرور' : 'Password'}
                    {editingUser && <span className="text-muted-foreground text-xs"> ({language === 'ar' ? 'اتركها فارغة للإبقاء' : 'leave empty to keep'})</span>}
                  </Label>
                  <Input
                    type="password"
                    value={formData.password}
                    onChange={(e) => setFormData(prev => ({ ...prev, password: e.target.value }))}
                    required={!editingUser}
                    data-testid="input-new-password"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>{language === 'ar' ? 'الاسم الكامل' : 'Full Name'}</Label>
                  <Input
                    value={formData.name}
                    onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    required
                    data-testid="input-new-name"
                  />
                </div>
                <div className="space-y-2">
                  <Label>{language === 'ar' ? 'الدور' : 'Role'}</Label>
                  <Select 
                    value={formData.role} 
                    onValueChange={(v) => setFormData(prev => ({ ...prev, role: v }))}
                  >
                    <SelectTrigger data-testid="select-role">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="sales">{language === 'ar' ? 'موظف مبيعات' : 'Sales Staff'}</SelectItem>
                      <SelectItem value="sales_admin">{language === 'ar' ? 'مدير مبيعات' : 'Sales Admin'}</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-3">
                <Label>{language === 'ar' ? 'الصلاحيات' : 'Permissions'}</Label>
                <div className="grid grid-cols-2 gap-3">
                  <div className="flex items-center justify-between p-2 border rounded">
                    <div className="flex items-center gap-2">
                      <ShoppingCart className="h-4 w-4" />
                      <span className="text-sm">{language === 'ar' ? 'نقطة البيع' : 'POS'}</span>
                    </div>
                    <Switch
                      checked={formData.canPos === 1}
                      onCheckedChange={(v) => setFormData(prev => ({ ...prev, canPos: v ? 1 : 0 }))}
                    />
                  </div>
                  <div className="flex items-center justify-between p-2 border rounded">
                    <div className="flex items-center gap-2">
                      <Package className="h-4 w-4" />
                      <span className="text-sm">{language === 'ar' ? 'المخزون' : 'Inventory'}</span>
                    </div>
                    <Switch
                      checked={formData.canInventory === 1}
                      onCheckedChange={(v) => setFormData(prev => ({ ...prev, canInventory: v ? 1 : 0 }))}
                    />
                  </div>
                  <div className="flex items-center justify-between p-2 border rounded">
                    <div className="flex items-center gap-2">
                      <Users className="h-4 w-4" />
                      <span className="text-sm">{language === 'ar' ? 'المستخدمين' : 'Users'}</span>
                    </div>
                    <Switch
                      checked={formData.canManageUsers === 1}
                      onCheckedChange={(v) => setFormData(prev => ({ ...prev, canManageUsers: v ? 1 : 0 }))}
                    />
                  </div>
                  <div className="flex items-center justify-between p-2 border rounded">
                    <div className="flex items-center gap-2">
                      <BarChart3 className="h-4 w-4" />
                      <span className="text-sm">{language === 'ar' ? 'التقارير' : 'Reports'}</span>
                    </div>
                    <Switch
                      checked={formData.canViewReports === 1}
                      onCheckedChange={(v) => setFormData(prev => ({ ...prev, canViewReports: v ? 1 : 0 }))}
                    />
                  </div>
                  <div className="flex items-center justify-between p-2 border rounded col-span-2">
                    <div className="flex items-center gap-2">
                      <Percent className="h-4 w-4" />
                      <span className="text-sm">{language === 'ar' ? 'تطبيق الخصومات' : 'Apply Discounts'}</span>
                    </div>
                    <Switch
                      checked={formData.canApplyDiscount === 1}
                      onCheckedChange={(v) => setFormData(prev => ({ ...prev, canApplyDiscount: v ? 1 : 0 }))}
                    />
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-between p-3 border rounded bg-muted/50">
                <div className="flex items-center gap-2">
                  <Shield className="h-4 w-4" />
                  <span>{language === 'ar' ? 'الحساب نشط' : 'Account Active'}</span>
                </div>
                <Switch
                  checked={formData.isActive === 1}
                  onCheckedChange={(v) => setFormData(prev => ({ ...prev, isActive: v ? 1 : 0 }))}
                />
              </div>

              <div className="flex gap-2 justify-end">
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>
                  {language === 'ar' ? 'إلغاء' : 'Cancel'}
                </Button>
                <Button 
                  type="submit" 
                  disabled={createMutation.isPending || updateMutation.isPending}
                  data-testid="button-save-user"
                >
                  {(createMutation.isPending || updateMutation.isPending) ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    language === 'ar' ? 'حفظ' : 'Save'
                  )}
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardContent className="pt-6">
          {isLoading ? (
            <div className="flex items-center justify-center h-64">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-start p-3">{language === 'ar' ? 'المستخدم' : 'User'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'الدور' : 'Role'}</th>
                    <th className="text-start p-3">{language === 'ar' ? 'الصلاحيات' : 'Permissions'}</th>
                    <th className="text-center p-3">{language === 'ar' ? 'الحالة' : 'Status'}</th>
                    <th className="text-end p-3">{language === 'ar' ? 'الإجراءات' : 'Actions'}</th>
                  </tr>
                </thead>
                <tbody>
                  {users.map(u => (
                    <tr key={u.id} className="border-b hover:bg-muted/50">
                      <td className="p-3">
                        <div>
                          <div className="font-medium">{u.name}</div>
                          <div className="text-muted-foreground text-xs">@{u.username}</div>
                        </div>
                      </td>
                      <td className="p-3">
                        <Badge variant={u.role === 'sales_admin' ? 'default' : 'secondary'}>
                          {u.role === 'sales_admin' 
                            ? (language === 'ar' ? 'مدير مبيعات' : 'Sales Admin')
                            : (language === 'ar' ? 'موظف مبيعات' : 'Sales Staff')
                          }
                        </Badge>
                      </td>
                      <td className="p-3">
                        <div className="flex flex-wrap gap-1">
                          {u.canPos === 1 && (
                            <Badge variant="outline" className="text-xs">
                              <ShoppingCart className="h-3 w-3 me-1" />
                              POS
                            </Badge>
                          )}
                          {u.canInventory === 1 && (
                            <Badge variant="outline" className="text-xs">
                              <Package className="h-3 w-3 me-1" />
                              {language === 'ar' ? 'مخزون' : 'Inv'}
                            </Badge>
                          )}
                          {u.canManageUsers === 1 && (
                            <Badge variant="outline" className="text-xs">
                              <Users className="h-3 w-3 me-1" />
                              {language === 'ar' ? 'مستخدمين' : 'Users'}
                            </Badge>
                          )}
                          {u.canViewReports === 1 && (
                            <Badge variant="outline" className="text-xs">
                              <BarChart3 className="h-3 w-3 me-1" />
                              {language === 'ar' ? 'تقارير' : 'Reports'}
                            </Badge>
                          )}
                          {u.canApplyDiscount === 1 && (
                            <Badge variant="outline" className="text-xs">
                              <Percent className="h-3 w-3 me-1" />
                              {language === 'ar' ? 'خصم' : 'Disc'}
                            </Badge>
                          )}
                        </div>
                      </td>
                      <td className="p-3 text-center">
                        {u.isActive === 1 ? (
                          <Badge variant="outline" className="border-green-500 text-green-600">
                            {language === 'ar' ? 'نشط' : 'Active'}
                          </Badge>
                        ) : (
                          <Badge variant="outline" className="border-red-500 text-red-600">
                            {language === 'ar' ? 'معطل' : 'Inactive'}
                          </Badge>
                        )}
                      </td>
                      <td className="p-3">
                        <div className="flex justify-end gap-1">
                          <Button
                            size="icon"
                            variant="ghost"
                            onClick={() => openEditDialog(u)}
                            data-testid={`button-edit-user-${u.id}`}
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                          {u.id !== user.id && (
                            <Button
                              size="icon"
                              variant="ghost"
                              className="text-destructive"
                              onClick={() => {
                                if (confirm(language === 'ar' ? 'هل أنت متأكد من حذف هذا المستخدم؟' : 'Are you sure you want to delete this user?')) {
                                  deleteMutation.mutate(u.id);
                                }
                              }}
                              data-testid={`button-delete-user-${u.id}`}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/AdminAttendance.tsx.content:
import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { useLanguage } from "@/contexts/LanguageContext";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { 
  Clock, 
  Calendar, 
  Users, 
  Loader2,
  Search,
  LogIn,
  LogOut,
  Timer,
  Banknote
} from "lucide-react";
import { AdminNav } from "@/components/AdminNav";
import type { SalesShift } from "@shared/schema";

interface AdminUser {
  id: string;
  username: string;
  name: string;
  role: string;
}

export default function AdminAttendance() {
  const [, setLocation] = useLocation();
  const { language } = useLanguage();
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState<"all" | "active" | "closed">("all");
  const [filterDate, setFilterDate] = useState("");

  const { data: currentAdmin, isLoading: authLoading, isError: authError } = useQuery<AdminUser>({
    queryKey: ['/api/admin/auth/me'],
    retry: false,
  });

  useEffect(() => {
    if (!authLoading && (authError || !currentAdmin)) {
      localStorage.removeItem("adminAuth");
      setLocation("/admin/login");
    }
  }, [authLoading, authError, currentAdmin, setLocation]);

  const { data: shifts = [], isLoading: shiftsLoading } = useQuery<SalesShift[]>({
    queryKey: ['/api/admin/shifts'],
    enabled: !!currentAdmin,
  });

  const formatPrice = (price: number | string | null) => {
    if (!price) return "٠";
    const num = typeof price === 'string' ? parseFloat(price) : price;
    return new Intl.NumberFormat('ar-IQ').format(num);
  };

  const formatDate = (dateVal: Date | string) => {
    const date = typeof dateVal === 'string' ? new Date(dateVal) : dateVal;
    return date.toLocaleDateString(language === 'ar' ? 'ar-IQ' : 'en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  const formatTime = (dateVal: Date | string | null) => {
    if (!dateVal) return "-";
    const date = typeof dateVal === 'string' ? new Date(dateVal) : dateVal;
    return date.toLocaleTimeString(language === 'ar' ? 'ar-IQ' : 'en-US', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const calculateDuration = (start: Date | string, end: Date | string | null) => {
    if (!end) return language === 'ar' ? 'قيد العمل' : 'Ongoing';
    const startDate = typeof start === 'string' ? new Date(start) : start;
    const endDate = typeof end === 'string' ? new Date(end) : end;
    const diffMs = endDate.getTime() - startDate.getTime();
    const hours = Math.floor(diffMs / (1000 * 60 * 60));
    const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
    return `${hours}:${minutes.toString().padStart(2, '0')}`;
  };

  const filteredShifts = shifts.filter(shift => {
    const matchesSearch = shift.salesUserName.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = filterStatus === 'all' || shift.status === filterStatus;
    const matchesDate = !filterDate || new Date(shift.startTime).toDateString() === new Date(filterDate).toDateString();
    return matchesSearch && matchesStatus && matchesDate;
  });

  const activeShiftsCount = shifts.filter(s => s.status === 'active').length;
  const todayShifts = shifts.filter(s => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return new Date(s.startTime) >= today;
  });

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  if (!currentAdmin) {
    return null;
  }

  return (
    <div className="min-h-screen bg-background" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <AdminNav currentAdmin={currentAdmin} />

      <div className="container mx-auto px-4 py-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <Clock className="h-6 w-6 text-primary" />
              {language === 'ar' ? 'حضور الموظفين' : 'Staff Attendance'}
            </h1>
            <p className="text-muted-foreground mt-1">
              {language === 'ar' ? 'تتبع أوقات الدخول والخروج لفريق المبيعات' : 'Track check-in and check-out times for sales staff'}
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-muted-foreground">
                    {language === 'ar' ? 'حاليا في العمل' : 'Currently Working'}
                  </p>
                  <p className="text-2xl font-bold text-green-600">{activeShiftsCount}</p>
                </div>
                <div className="h-12 w-12 rounded-full bg-green-500/10 flex items-center justify-center">
                  <Users className="h-6 w-6 text-green-500" />
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-muted-foreground">
                    {language === 'ar' ? 'ورديات اليوم' : "Today's Shifts"}
                  </p>
                  <p className="text-2xl font-bold text-blue-600">{todayShifts.length}</p>
                </div>
                <div className="h-12 w-12 rounded-full bg-blue-500/10 flex items-center justify-center">
                  <Calendar className="h-6 w-6 text-blue-500" />
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-muted-foreground">
                    {language === 'ar' ? 'إجمالي السجلات' : 'Total Records'}
                  </p>
                  <p className="text-2xl font-bold text-primary">{shifts.length}</p>
                </div>
                <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center">
                  <Timer className="h-6 w-6 text-primary" />
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        <Card>
          <CardHeader className="pb-4">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <CardTitle className="text-lg">
                {language === 'ar' ? 'سجل الحضور' : 'Attendance Log'}
              </CardTitle>

              <div className="flex flex-wrap items-center gap-3">
                <div className="relative">
                  <Search className="absolute start-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder={language === 'ar' ? 'بحث بالاسم...' : 'Search by name...'}
                    className="ps-9 w-48"
                    data-testid="input-search-attendance"
                  />
                </div>

                <Select value={filterStatus} onValueChange={(v) => setFilterStatus(v as "all" | "active" | "closed")}>
                  <SelectTrigger className="w-36" data-testid="select-status-filter">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">{language === 'ar' ? 'الكل' : 'All'}</SelectItem>
                    <SelectItem value="active">{language === 'ar' ? 'قيد العمل' : 'Active'}</SelectItem>
                    <SelectItem value="closed">{language === 'ar' ? 'انتهى' : 'Closed'}</SelectItem>
                  </SelectContent>
                </Select>

                <Input
                  type="date"
                  value={filterDate}
                  onChange={(e) => setFilterDate(e.target.value)}
                  className="w-40"
                  data-testid="input-date-filter"
                />

                {filterDate && (
                  <Button variant="ghost" size="sm" onClick={() => setFilterDate("")}>
                    {language === 'ar' ? 'مسح' : 'Clear'}
                  </Button>
                )}
              </div>
            </div>
          </CardHeader>

          <CardContent>
            {shiftsLoading ? (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="h-8 w-8 animate-spin" />
              </div>
            ) : filteredShifts.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">
                <Clock className="h-12 w-12 mx-auto mb-4 opacity-20" />
                <p>{language === 'ar' ? 'لا توجد سجلات حضور' : 'No attendance records found'}</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>{language === 'ar' ? 'الموظف' : 'Employee'}</TableHead>
                      <TableHead>{language === 'ar' ? 'التاريخ' : 'Date'}</TableHead>
                      <TableHead>{language === 'ar' ? 'وقت الدخول' : 'Check-in'}</TableHead>
                      <TableHead>{language === 'ar' ? 'وقت الخروج' : 'Check-out'}</TableHead>
                      <TableHead>{language === 'ar' ? 'المدة' : 'Duration'}</TableHead>
                      <TableHead>{language === 'ar' ? 'الحالة' : 'Status'}</TableHead>
                      <TableHead>{language === 'ar' ? 'المبيعات' : 'Sales'}</TableHead>
                      <TableHead>{language === 'ar' ? 'المعاملات' : 'Transactions'}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredShifts.map((shift) => (
                      <TableRow key={shift.id} data-testid={`attendance-row-${shift.id}`}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center">
                              <Users className="h-4 w-4 text-primary" />
                            </div>
                            <span className="font-medium">{shift.salesUserName}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 text-sm">
                            <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                            {formatDate(shift.startTime)}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 text-sm text-green-600">
                            <LogIn className="h-3.5 w-3.5" />
                            {formatTime(shift.startTime)}
                          </div>
                        </TableCell>
                        <TableCell>
                          {shift.endTime ? (
                            <div className="flex items-center gap-1 text-sm text-red-600">
                              <LogOut className="h-3.5 w-3.5" />
                              {formatTime(shift.endTime)}
                            </div>
                          ) : (
                            <span className="text-muted-foreground">-</span>
                          )}
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 text-sm">
                            <Timer className="h-3.5 w-3.5 text-muted-foreground" />
                            {calculateDuration(shift.startTime, shift.endTime)}
                          </div>
                        </TableCell>
                        <TableCell>
                          {shift.status === 'active' ? (
                            <Badge className="bg-green-500/10 text-green-600 border-green-200">
                              {language === 'ar' ? 'قيد العمل' : 'Working'}
                            </Badge>
                          ) : (
                            <Badge variant="outline">
                              {language === 'ar' ? 'انتهى' : 'Ended'}
                            </Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 text-sm">
                            <Banknote className="h-3.5 w-3.5 text-muted-foreground" />
                            {formatPrice(shift.totalSales)} 
                            <span className="text-xs text-muted-foreground">
                              {language === 'ar' ? 'د.ع' : 'IQD'}
                            </span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge variant="secondary">
                            {shift.totalTransactions || 0}
                          </Badge>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

